331	type persistTerm struct {
332		Wire  int    `json:"wire"`
333		Coeff string `json:"coeff"`
334	}
335	
336	type persistConstraint struct {
337		A []persistTerm `json:"a"`
338		B []persistTerm `json:"b"`
339		C []persistTerm `json:"c"`
340	}
341	
342	// persistDefinition is the canonical, already-validated constraint set bound
343	// to one circuit version. The public/private partition is owned by the
344	// circuit record and is deliberately not duplicated here, so it can never
345	// drift from the declared counts.
346	type persistDefinition struct {
347		Modulus     string              `json:"modulus"`
348		Constraints []persistConstraint `json:"constraints"`
349	}
350	
351	// persistArtifact is a compiled artifact: the version's identity and
352	// constraint count bound to its recomputable SHA-256 hash.
353	type persistArtifact struct {
354		Name        string `json:"name"`
355		Version     int    `json:"version"`
356		Modulus     int64  `json:"modulus"`
357		Constraints int    `json:"constraints"`
358		Hash        string `json:"hash"`
