361	// Store is a persistent workbench backed by one local data directory.
362	//
363	// All operations are safe for concurrent use by multiple goroutines and by
364	// several processes pointed at the same directory: an in-process mutex plus a
365	// process-shared flock serialize commits, and every commit is an atomic
366	// temp-file/fsync/rename replacement. Open the directory with Open and call
367	// Close when done.
368	type Store struct {
369		dir  string
370		mu   sync.Mutex
371		lock *os.File
372	
373		data envelope
374	}
375	
376	// resolveDataDir turns the Open argument into the absolute physical
377	// directory the store will be permanently pinned to.
378	//
379	// The argument is resolved exactly the way the kernel reaches it on an
380	// open(2) — relative components anchored to the process's current working
381	// directory at Open time, one component at a time, every symlink expanded at
382	// the position where the walk meets it. No lexical Clean is applied first:
383	// filepath.Abs/Clean would fold "entry/.." before the symlink was ever
384	// examined, so a ".." standing after a symlink pops the link's resolved
385	// target rather than the link's own spelling, and a/link/../x cannot be made
386	// to name a/x and select another data directory. Any trailing segment that
387	// does not exist yet (a data directory to be created by Open, or a
388	// not-yet-existing parent) is appended verbatim to the resolved physical
389	// prefix, and MkdirAll creates it beneath that prefix; a ".." after such a
390	// missing component cannot be walked faithfully (the kernel reports ENOENT
391	// there instead of folding the literal path) and fails the resolution. A
392	// dangling entry link — the entry itself is a symlink whose target does not
393	// exist — resolves through the link target's spelling and is created there.
394	func resolveDataDir(dir string) (string, error) {
395		resolved, err := resolveExistingPrefix(dir)
396		if err != nil {
397			return "", err
398		}
399		if !filepath.IsAbs(resolved) {
400			// The walk itself stayed relative to the Open-time working directory;
401			// only now, after every symlink has been expanded and every ".."
402			// popped in walk order, anchor the result absolutely for pinning.
403			resolved, err = filepath.Abs(resolved)
404			if err != nil {
405				return "", err
406			}
407		}
408		return resolved, nil
409	}
410	
411	// maxDataDirLinks bounds symlink expansion while resolving the data
412	// directory, matching the kernel's ELOOP guard: a link cycle must fail Open
413	// rather than loop forever.
414	const maxDataDirLinks = 255
415	
416	// resolveExistingPrefix walks path the way a kernel path walk reaches it,
417	// accepting both absolute and Open-cwd-relative paths. Symlinks are expanded
418	// inline where the walk meets them and ".." pops the directory the walk is
419	// actually standing in (a link target, not the link spelling). Unlike
420	// filepath.EvalSymlinks the walk tolerates a missing tail: at the first
421	// component that cannot be Lstat'd, that component and the remaining literal
422	// components are appended to the resolved prefix so Open can create the chain
423	// with MkdirAll — unless the remainder contains "..", which could not be
424	// resolved against a non-existent entry and is an error.
425	func resolveExistingPrefix(path string) (string, error) {
426		volLen := len(filepath.VolumeName(path))
427		pathSeparator := string(os.PathSeparator)
428		if volLen < len(path) && os.IsPathSeparator(path[volLen]) {
429			volLen++
430		}
431		vol := path[:volLen] // "/" (or a drive/UNC root elsewhere); "" when relative
432		dest := vol
433		linksWalked := 0
434		for start, end := volLen, volLen; start < len(path); start = end {
435			for start < len(path) && os.IsPathSeparator(path[start]) {
436				start++
437			}
438			end = start
439			for end < len(path) && !os.IsPathSeparator(path[end]) {
440				end++
441			}
442			if end == start {
443				break
444			}
445			comp := path[start:end]
446			if comp == "." {
447				continue
448			}
449			if comp == ".." {
450				// Pop what the walk has actually reached; symlinks have already
451				// been expanded into dest, so this removes the target, never the
452				// link spelling.
453				r := -1
454				for i := len(dest) - 1; i >= volLen; i-- {
455					if os.IsPathSeparator(dest[i]) {
456						r = i
457						break
458					}
459				}
460				if r < volLen || dest[r+1:] == ".." {
461					if len(dest) > volLen {
462						dest += pathSeparator
463					}
464					dest += ".."
465				} else {
466					dest = dest[:r]
467				}
468				continue
469			}
470	
471			if len(dest) > len(filepath.VolumeName(dest)) && !os.IsPathSeparator(dest[len(dest)-1]) {
472				dest += pathSeparator
473			}
474			dest += comp
475	
476			fi, err := os.Lstat(dest)
477			if err != nil {
478				if !os.IsNotExist(err) {
479					return "", err
480				}
481				// Missing tail: append the remainder literally, refusing a
482				// remainder containing ".." (unresolvable against this absent
483				// entry), and let MkdirAll create the chain.
484				for r := end; r < len(path); {
485					for r < len(path) && os.IsPathSeparator(path[r]) {
486						r++
487					}
488					s := r
489					for r < len(path) && !os.IsPathSeparator(path[r]) {
490						r++
491					}
492					switch path[s:r] {
493					case "", ".":
494					case "..":
495						return "", fmt.Errorf("cannot resolve %q: %q does not exist and is followed by a parent reference", path, comp)
496					default:
497						dest += pathSeparator + path[s:r]
498					}
499				}
500				return filepath.Clean(dest), nil
501			}
502			if fi.Mode()&os.ModeSymlink == 0 {
503				if !fi.Mode().IsDir() && end < len(path) {
504					return "", fmt.Errorf("cannot resolve %q: %q is not a directory", path, comp)
505				}
506				continue
507			}
508			linksWalked++
509			if linksWalked > maxDataDirLinks {
510				return "", fmt.Errorf("cannot resolve %q: too many symlinks", path)
511			}
512			link, err := os.Readlink(dest)
513			if err != nil {
514				return "", err
515			}
516			// Expand the link exactly at the walk position: the still-queued
517			// components (including any "..") continue from the target rather
518			// than from the link spelling.
519			path = link + path[end:]
520			switch {
521			case len(link) > 0 && os.IsPathSeparator(link[0]):
522				volLen = 1
523				vol = path[:1]
524				dest = vol
525				end = 1
526			default:
527				if v := filepath.VolumeName(link); v != "" {
528					if len(link) > len(v) && os.IsPathSeparator(link[len(v)]) {
529						v += string(os.PathSeparator)
530					}
531					volLen = len(v)
532					vol = v
533					dest = vol
534					end = volLen
535					break
536				}
537				// Relative link: it names a path from the directory holding the
538				// link, which is dest without the link's own component.
539				r := -1
540				for i := len(dest) - 1; i >= volLen; i-- {
541					if os.IsPathSeparator(dest[i]) {
542						r = i
543						break
544					}
545				}
546				if r < volLen {
547					dest = vol
548				} else {
549					dest = dest[:r]
550				}
551				end = 0
552			}
553		}
554		return filepath.Clean(dest), nil
555	}
556	
557	// Open opens (creating if needed) the workbench data in dir. If the
558	// directory does not exist it is created. Existing committed data is loaded
559	// and fully validated before Open returns; on a corrupt, truncated or
560	// unsupported-format file Open returns an error wrapping ErrDataCorrupt and
561	// leaves every file in the directory untouched.
562	//
563	// dir is resolved against the process's current working directory at Open
564	// time and pinned for the store's lifetime: a relative path such as
565	// "bench-data" names one fixed directory from the moment Open succeeds, and
566	// later working-directory changes never redirect the store's reads, writes,
567	// lock or Dir to another location.
568	//
569	// The pinning is to the actual directory opened, not to the literal path
570	// spelling: symlinks already present in the file system — whether dir itself
571	// is a link or one of its parent directories is — are resolved segment by
572	// segment at Open time, and Dir reports the resulting absolute physical
573	// directory. Repointing or removing an entry link afterwards never moves the
574	// store: queries, commits, the lock file and compiled-artifact bindings keep
575	// using the original directory even after the link changes or vanishes. A
576	// ".." following a symlink is resolved the way the kernel walk reaches it
577	// (the already-resolved link target is popped), never by lexical folding of
578	// the literal path, so it cannot select a different data directory. A
579	// not-yet-existing data directory named through a valid (possibly
580	// symlinked) parent is created under the parent's physical location. Paths
581	// to constraint definitions and input files passed to individual operations
582	// are not pinned this way — they keep being resolved against the caller's
583	// working directory at call time.
584	func Open(dir string) (*Store, error) {
585		if dir == "" {
586			return nil, invalidf("data directory must not be empty")
587		}
588		// Resolve and pin the physical location now, before anything else can
589		// change. resolveDataDir walks the argument the way the kernel reaches
590		// it — relative to the process working directory at Open time, symlinks
591		// expanded segment by segment in walk order and ".." popped in place — so
592		// a later chdir, a repointed or deleted entry link, or a ".." sitting
593		// after a symlink cannot move reads, writes, the lock or Dir onto another
594		// directory. The result is absolute and names the real directory opened.
595		dir, err := resolveDataDir(dir)
596		if err != nil {
597			return nil, fmt.Errorf("cannot resolve data directory %q: %w", dir, err)
598		}
599		if err := os.MkdirAll(dir, 0o755); err != nil {
600			return nil, fmt.Errorf("cannot create data directory %q: %w", dir, err)
601		}
602		lockPath := filepath.Join(dir, dirLockFile)
603		lock, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o644)
604		if err != nil {
605			return nil, fmt.Errorf("cannot open lock file in %q: %w", dir, err)
606		}
607		// Serialize against other processes while we read / validate.
608		if err := lockExclusive(lock); err != nil {
609			lock.Close()
610			return nil, fmt.Errorf("cannot lock data directory %q: %w", dir, err)
611		}
612	
613		s := &Store{dir: dir, lock: lock}
614		if err := s.loadLocked(); err != nil {
615			unlockLock(lock)
616			lock.Close()
617			return nil, err
618		}
619		// The lock is taken again per operation; holding it for the store's
620		// lifetime would forbid two open handles on one directory.
621		if err := unlockLock(lock); err != nil {
622			lock.Close()
623			return nil, fmt.Errorf("cannot release open lock on %q: %w", dir, err)
624		}
625		return s, nil
626	}
627	
628	// Close releases the directory lock. It does not discard committed data.
629	func (s *Store) Close() error {
630		s.mu.Lock()
631		defer s.mu.Unlock()
632		if s.lock == nil {
633			return nil
634		}
635		var first error
636		if err := unlockLock(s.lock); err != nil {
637			first = err
638		}
639		if err := s.lock.Close(); err != nil && first == nil {
640			first = err
641		}
642		s.lock = nil
643		return first
644	}
645	
646	// Dir reports the data directory backing the store.
647	func (s *Store) Dir() string { return s.dir }
648	
649	func (s *Store) dataPath() string { return filepath.Join(s.dir, dirDataFile) }
650	func (s *Store) tmpPath() string  { return filepath.Join(s.dir, dirTmpFile) }
651	
652	// loadLocked reads and validates the committed file. Caller must hold the
653	// exclusive flock; the in-process mutex is taken by the public Open path.
654	func (s *Store) loadLocked() error {
655		raw, err := os.ReadFile(s.dataPath())
656		if errors.Is(err, os.ErrNotExist) {
657			s.data = envelope{Format: FormatVersion}
658			return nil
659		}
660		if err != nil {
661			return fmt.Errorf("cannot read data file %q: %w", s.dataPath(), err)
662		}
663		if len(strings.TrimSpace(string(raw))) == 0 {
664			return corruptf("data file %q is empty or truncated; refusing to treat it as a new directory", s.dataPath())
665		}
666	
667		var env envelope
668		if err := json.Unmarshal(raw, &env); err != nil {
669			// Shape failures surfaced by the persisted-definition decoders are
670			// integrity failures, not JSON syntax errors; report their detail
671			// instead of the generic "not valid JSON" wording.
672			var se StoreError
673			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
674				return corruptf("data file %q failed integrity validation: %s; original file left in place", s.dataPath(), se.Detail)
675			}
676			return corruptf("data file %q is not valid JSON (%v); original file left in place", s.dataPath(), err)
677		}
678		if env.Format == 0 {
679			return corruptf("data file %q has no format version; original file left in place", s.dataPath())
680		}
681		if env.Format != FormatVersion {
682			return corruptf("data file %q uses unsupported format version %d (this build supports %d); original file left in place",
683				s.dataPath(), env.Format, FormatVersion)
684		}
685		if err := validateEnvelope(env); err != nil {
686			return corruptf("data file %q failed integrity validation: %v; original file left in place", s.dataPath(), err)
687		}
688		s.data = env
689		return nil
690	}
691	
692	// commitLocked writes the pending state atomically: temp file → fsync →
693	// rename → fsync directory. Caller must hold both the in-process mutex and
694	// the exclusive flock; all in-memory mutations must already have happened and
695	// been rule-checked, so a failure here occurs before any success is reported.
696	func (s *Store) commitLocked() error {
697		s.data.Format = FormatVersion
698		// Stable output: records are stored sorted so files are deterministic.
699		sortEnvelope(&s.data)
700	
701		payload, err := json.MarshalIndent(&s.data, "", "  ")
702		if err != nil {
703			return fmt.Errorf("cannot encode data: %w", err)
704		}
705		payload = append(payload, '\n')
706	
707		tmp := s.tmpPath()
708		f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o644)
709		if err != nil {
710			return fmt.Errorf("cannot stage write in %q: %w", s.dir, err)
711		}
712		if _, err := f.Write(payload); err != nil {
713			f.Close()
714			os.Remove(tmp)
715			return fmt.Errorf("cannot write staged data: %w", err)
716		}
717		if err := f.Sync(); err != nil {
718			f.Close()
719			os.Remove(tmp)
720			return fmt.Errorf("cannot flush staged data: %w", err)
721		}
722		if err := f.Close(); err != nil {
723			os.Remove(tmp)
724			return fmt.Errorf("cannot finish staged data: %w", err)
725		}
726		if err := os.Rename(tmp, s.dataPath()); err != nil {
727			os.Remove(tmp)
728			return fmt.Errorf("cannot commit data file: %w", err)
729		}
730		if err := syncDir(s.dir); err != nil {
731			// The rename already happened; lack of dir fsync only weakens crash
732			// durability, never correctness of what is visible now.
733			return nil
734		}
735		return nil
736	}
737	
738	// withLock runs fn under the in-process mutex and an exclusive flock, then
739	// atomically commits when fn requests it. The on-disk state is re-read after
740	// acquiring the lock, so concurrent commits from another process or another
741	// handle are always observed. Operations validate before mutating; a rejected
742	// operation (commit=false or an error) writes nothing and leaves committed
743	// state unchanged.
744	func (s *Store) withLock(fn func() (commit bool, err error)) error {
745		s.mu.Lock()
746		defer s.mu.Unlock()
747		if s.lock == nil {
748			return invalidf("store is closed")
749		}
750		if err := lockExclusive(s.lock); err != nil {
751			return fmt.Errorf("cannot lock data directory: %w", err)
752		}
753		defer unlockLock(s.lock)
754	
755		if err := s.loadLocked(); err != nil {
756			return err
757		}
758		commit, err := fn()
759		if err != nil {
760			return err
761		}
762		if !commit {
763			return nil
764		}
765		return s.commitLocked()
766	}
767	
768	// withLockRead runs fn under a shared flock over freshly reloaded state.
769	func (s *Store) withLockRead(fn func() error) error {
770		s.mu.Lock()
771		defer s.mu.Unlock()
772		if s.lock == nil {
773			return invalidf("store is closed")
774		}
775		if err := lockShared(s.lock); err != nil {
776			return fmt.Errorf("cannot lock data directory: %w", err)
777		}
778		defer unlockLock(s.lock)
779		if err := s.loadLocked(); err != nil {
780			return err
781		}
782		return fn()
783	}
784	
785	func sortEnvelope(env *envelope) {
786		sort.Slice(env.Circuits, func(i, j int) bool {
787			if env.Circuits[i].Name != env.Circuits[j].Name {
788				return env.Circuits[i].Name < env.Circuits[j].Name
789			}
790			return env.Circuits[i].Version < env.Circuits[j].Version
791		})
792		sort.Slice(env.Setups, func(i, j int) bool {
793			if env.Setups[i].Name != env.Setups[j].Name {
794				return env.Setups[i].Name < env.Setups[j].Name
795			}
796			return env.Setups[i].Version < env.Setups[j].Version
797		})
798		sort.Slice(env.Jobs, func(i, j int) bool { return env.Jobs[i].ID < env.Jobs[j].ID })
799		sort.Slice(env.Artifacts, func(i, j int) bool {
800			if env.Artifacts[i].Name != env.Artifacts[j].Name {
801				return env.Artifacts[i].Name < env.Artifacts[j].Name
802			}
803			return env.Artifacts[i].Version < env.Artifacts[j].Version
804		})
805	}
806	
807	// validateEnvelope re-checks every invariant on load so a tampered or
808	// hand-edited file cannot bypass the domain rules.
809	//
810	// A stored constraint definition is parsed and canonicalized exactly once
811	// per load: the circuit pass validates every defined version against its
812	// declared counts and keeps the resulting canonical form, and the artifact
813	// pass reuses that same form to verify the recorded modulus, constraint
814	// count and hash. The map is built fresh on each call, so the reuse never
815	// carries a judgment across loads — every read validates the bytes found on
816	// disk at that moment.
817	func validateEnvelope(env envelope) error {
818		seenCircuit := make(map[[2]string]bool)
819		circuitOK := make(map[[2]string]bool)
820		canonicalDefs := make(map[[2]string]*canonicalDefinition)
821		for i, c := range env.Circuits {
822			key := [2]string{c.Name, itoa(c.Version)}
823			if c.Name == "" || strings.TrimSpace(c.Name) == "" {
824				return fmt.Errorf("circuit #%d has an empty or blank name", i+1)
825			}
826			if c.Version <= 0 {
827				return fmt.Errorf("circuit %q version %d is not a positive integer", c.Name, c.Version)
828			}
829			if seenCircuit[key] {
830				return fmt.Errorf("circuit %q version %d appears more than once", c.Name, c.Version)
831			}
832			seenCircuit[key] = true
833			if c.Constraints <= 0 {
834				return fmt.Errorf("circuit %q v%d: constraints must be > 0", c.Name, c.Version)
835			}
836			if c.PublicInputs < 0 || c.PrivateInputs < 0 {
837				return fmt.Errorf("circuit %q v%d: input counts must not be negative", c.Name, c.Version)
838			}
839			// The same representability rule the write path enforces: wire 0 plus
840			// every declared input must fit inside the platform's int. A record
841			// beyond that bound can never have been written by this build and
842			// cannot be checked safely, so the directory is corrupt rather than
843			// silently narrowed or read with a wrapped-around layout.
844			if !inputLayoutRepresentable(c.PublicInputs, c.PrivateInputs) {
845				return fmt.Errorf("circuit %q v%d: input layout is not representable: 1 constant wire + %d public + %d private inputs exceeds the platform limit of %d wires",
846					c.Name, c.Version, c.PublicInputs, c.PrivateInputs, maxInputWires)
847			}
848			if c.Definition != nil {
849				def, err := validatePersistDefinition(c.Name, c.Version, c.Constraints, c.PublicInputs, c.PrivateInputs, c.Definition)
850				if err != nil {
851					return err
852				}
853				canonicalDefs[key] = def
854			}
855			circuitOK[key] = true
856		}
857		seenSetup := make(map[[2]string]bool)
858		for i, p := range env.Setups {
859			key := [2]string{p.Name, itoa(p.Version)}
860			if !circuitOK[key] {
861				return fmt.Errorf("setup #%d belongs to unknown circuit %q v%d", i+1, p.Name, p.Version)
862			}
863			c := findPersistCircuit(env.Circuits, p.Name, p.Version)
864			if c == nil || !c.Frozen {
865				return fmt.Errorf("setup belongs to non-frozen circuit %q v%d", p.Name, p.Version)
866			}
867			if seenSetup[key] {
868				return fmt.Errorf("setup for %q v%d appears more than once", p.Name, p.Version)
869			}
870			seenSetup[key] = true
871		}
872		seenJob := make(map[string]bool)
873		for i, j := range env.Jobs {
874			if j.ID == "" || strings.TrimSpace(j.ID) == "" {
875				return fmt.Errorf("job #%d has an empty or blank id", i+1)
876			}
877			if seenJob[j.ID] {
878				return fmt.Errorf("job %q appears more than once", j.ID)
879			}
880			seenJob[j.ID] = true
881			if j.Kind != "prove" {
882				return fmt.Errorf("job %q has unsupported kind %q", j.ID, j.Kind)
883			}
884			if j.Attempt <= 0 {
885				return fmt.Errorf("job %q: attempt must be a positive integer", j.ID)
886			}
887			key := [2]string{j.Circuit, itoa(j.Version)}
888			if !circuitOK[key] {
889				return fmt.Errorf("job %q binds to unknown circuit %q v%d", j.ID, j.Circuit, j.Version)
890			}
891			c := findPersistCircuit(env.Circuits, j.Circuit, j.Version)
892			if c == nil || !c.Frozen {
893				return fmt.Errorf("job %q binds to non-frozen circuit %q v%d", j.ID, j.Circuit, j.Version)
894			}
895			if !seenSetup[key] {
896				return fmt.Errorf("job %q binds to circuit %q v%d without a trusted setup", j.ID, j.Circuit, j.Version)
897			}
898			// A recorded compiled-artifact binding must still resolve against the
899			// pinned version's artifact; a dangling or mismatched binding makes
900			// the file unreadable rather than silently dropping the binding.
901			if j.CompiledHash != "" {
902				artifact := findArtifact(env.Artifacts, j.Circuit, j.Version)
903				if artifact == nil {
904					return fmt.Errorf("job %q binds to compiled artifact of %q v%d which is missing", j.ID, j.Circuit, j.Version)
905				}
906				if artifact.Hash != j.CompiledHash {
907					return fmt.Errorf("job %q compiled hash %q does not match the artifact of %q v%d (hash %q)",
908						j.ID, j.CompiledHash, j.Circuit, j.Version, artifact.Hash)
909				}
910			}
911		}
912		seenArtifact := make(map[[2]string]bool)
913		for i, a := range env.Artifacts {
914			key := [2]string{a.Name, itoa(a.Version)}
915			if !circuitOK[key] {
916				return fmt.Errorf("artifact #%d belongs to unknown circuit %q v%d", i+1, a.Name, a.Version)
917			}
918			c := findPersistCircuit(env.Circuits, a.Name, a.Version)
919			if c == nil || !c.Frozen {
920				return fmt.Errorf("artifact belongs to non-frozen circuit %q v%d", a.Name, a.Version)
921			}
922			if seenArtifact[key] {
923				return fmt.Errorf("artifact for %q v%d appears more than once", a.Name, a.Version)
924			}
925			seenArtifact[key] = true
926			if c.Definition == nil {
927				return fmt.Errorf("artifact for %q v%d has no constraint definition", a.Name, a.Version)
928			}
929			if a.Constraints != c.Constraints {
930				return fmt.Errorf("artifact for %q v%d constraint count %d disagrees with the version's %d",
931					a.Name, a.Version, a.Constraints, c.Constraints)
932			}
933			// The circuit pass above already validated and canonicalized this
934			// version's definition (every artifact requires a defined version,
935			// checked just above), so the artifact check reuses that one result
936			// instead of re-parsing and re-normalizing the same stored definition.
937			def := canonicalDefs[key]
938			if int64(a.Modulus) != def.modulus || len(def.constraints) != a.Constraints {
939				return fmt.Errorf("artifact for %q v%d is inconsistent with its stored definition", a.Name, a.Version)
940			}
941			wantHash := artifactHash(a.Name, a.Version, def)
942			if a.Hash != wantHash {
943				return fmt.Errorf("artifact for %q v%d hash %q does not recompute from the definition (want %q)",
944					a.Name, a.Version, a.Hash, wantHash)
945			}
946		}
947		return nil
948	}
949	
950	// validatePersistDefinition re-validates a stored definition against its
951	// version's declared counts: prime modulus, in-range wires and an exact
952	// constraint count match. On success it returns the canonical form built
953	// during validation, so a later check against the same version's artifact
954	// reuses it instead of parsing and normalizing the definition a second time.
955	func validatePersistDefinition(name string, version, constraints, public, private int, def *persistDefinition) (*canonicalDefinition, error) {
956		parsed, err := definitionFromPersist(*def, public, private)
957		if err != nil {
958			return nil, fmt.Errorf("circuit %q v%d has a corrupt constraint definition: %w", name, version, err)
959		}
960		if !parsed.compatibleWith(constraints, public, private) {
961			return nil, fmt.Errorf("circuit %q v%d definition is incompatible with its declared counts", name, version)
962		}
963		return parsed, nil
964	}
965	
966	func findPersistCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
967		for i := range cs {
968			if cs[i].Name == name && cs[i].Version == version {
969				return &cs[i]
970			}
971		}
972		return nil
973	}
974	
975	func itoa(v int) string { return fmt.Sprintf("%d", v) }
976

