package zkcircuit

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"sync"
)

// on-disk layout inside the data directory:
//
//	data.json    – the committed state (JSON envelope, atomically replaced)
//	data.json.tmp– staging file for the next commit (rename(2) target)
//	lock         – flock file serializing concurrent processes
//
// The envelope carries an explicit format version: files written by an
// incompatible future build are refused rather than silently migrated or
// overwritten.
const (
	dirDataFile = "data.json"
	dirTmpFile  = "data.json.tmp"
	dirLockFile = "lock"

	// FormatVersion is the on-disk format this build writes and accepts.
	FormatVersion = 1
)

// envelope is the persisted state container.
//
// Circuits are kept as raw JSON during decoding so persistCircuit's strict
// UnmarshalJSON — rather than encoding/json's silent zero-value filling —
// decides what a committed circuit record may look like. UnmarshalJSON first
// walks the token stream (scanEnvelopeDuplicates) and rejects a repeated
// object key anywhere encoding/json would otherwise keep the last value. At
// the envelope's top level that comparison is case-insensitive for the five
// known fields (format/circuits/setups/jobs/artifacts): a second spelling
// that differs only in ASCII letter case — including one JSON-escaped — names
// the same field and corrupts the read instead of overriding it. A spelling
// that Unicode case-folds onto one of those fields yet is not an ASCII case
// variant ("circuitſ" with U+017F long s, directly written or ſ-escaped)
// is likewise corruption even when it is the only spelling present, since
// encoding/json's own tag matching would fill the field from it; a later
// "circuitſ": [] must never read the circuits as empty and drop them on the
// next commit.
type envelope struct {
	Format    int               `json:"format"`
	Circuits  []persistCircuit  `json:"circuits"`
	Setups    []persistSetup    `json:"setups"`
	Jobs      []persistJob      `json:"jobs"`
	Artifacts []persistArtifact `json:"artifacts,omitempty"`
}

// envelopeWire is the decoding-only shape: circuit records arrive raw so
// their own strict decoder can require every field explicitly.
type envelopeWire struct {
	Format    int               `json:"format"`
	Circuits  []json.RawMessage `json:"circuits"`
	Setups    []persistSetup    `json:"setups"`
	Jobs      []persistJob      `json:"jobs"`
	Artifacts []persistArtifact `json:"artifacts,omitempty"`
}

func (e *envelope) UnmarshalJSON(raw []byte) error {
	// Reject repeated keys before decoding: encoding/json silently keeps the
	// last value of a duplicate. The walk is layered so a repeated field is
	// attributed to the record it belongs to (a duplicate "frozen" inside
	// circuit #3, not a generic envelope complaint).
	if err := scanEnvelopeDuplicates(raw); err != nil {
		return err
	}
	var wire envelopeWire
	if err := json.Unmarshal(raw, &wire); err != nil {
		var se StoreError
		if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
			return err // an inner record decoder already named the problem
		}
		return corruptf("data file envelope is not valid JSON: %v", err)
	}
	e.Format = wire.Format
	e.Setups = wire.Setups
	e.Jobs = wire.Jobs
	e.Artifacts = wire.Artifacts
	if wire.Circuits == nil {
		e.Circuits = nil
	} else {
		e.Circuits = make([]persistCircuit, len(wire.Circuits))
	}
	for i, craw := range wire.Circuits {
		var record persistCircuit
		if err := json.Unmarshal(craw, &record); err != nil {
			var se StoreError
			if errors.As(err, &se) {
				// Re-tag as one corruption error carrying the record index,
				// so the detail survives errors.As unwrapping in loadLocked.
				return StoreError{Kind: ErrDataCorrupt.Kind,
					Detail: fmt.Sprintf("circuit record #%d: %s", i+1, se.Detail)}
			}
			return corruptf("circuit record #%d: %v", i+1, err)
		}
		e.Circuits[i] = record
	}
	return nil
}

// envelopeTopFields are the five fields an envelope may carry. Their
// canonical (standard lowercase) spellings are the wire tags on envelope and
// envelopeWire; JSON keys are tokenized after unescaping.
var envelopeTopFields = []string{"format", "circuits", "setups", "jobs", "artifacts"}

// canonicalEnvelopeField reports the standard lowercase name of one of the
// five envelope fields when key names it under any ASCII letter-case spelling
// ("format", "FORMAT", "FoRmAt", …). Keys are already JSON-unescaped by the
// tokenizer, so an escaped spelling of any such form lands here too. A
// non-canonical key (different length or a mismatching byte, including
// non-ASCII lookalikes and unknown fields such as "CIRCUIT") returns "".
func canonicalEnvelopeField(key string) string {
	for _, field := range envelopeTopFields {
		if len(key) != len(field) {
			continue
		}
		i := 0
		for i < len(key) {
			c := key[i]
			if c >= 'A' && c <= 'Z' {
				c += 'a' - 'A'
			}
			if c != field[i] {
				break
			}
			i++
		}
		if i == len(field) {
			return field
		}
	}
	return ""
}

// envelopeFieldLookalike reports the standard lowercase name of one of the
// five envelope fields when key names it under a spelling encoding/json's
// struct-tag matching would fold onto the field but which is not an accepted
// ASCII letter-case spelling (canonicalEnvelopeField reports those). Tag
// matching folds with the Unicode simple case-folding rules
// (strings.EqualFold), so "circuitſ" (U+017F long s, written directly or as
// the JSON escape u017f — keys arrive here already unescaped) names the
// circuits field exactly like "circuits", even standing alone. Such a
// lookalike is damage whatever its value: a later "circuitſ": [] would
// otherwise override a populated circuits array through last-value-wins and
// the records would vanish on the next commit. A key that does not fold onto
// any known field — an unrelated unknown name such as "note", or "cİrcuits"
// with U+0130 dotted capital I, which does not fold — returns "" and keeps
// the ordinary unknown-member handling.
func envelopeFieldLookalike(key string) string {
	if canonicalEnvelopeField(key) != "" {
		return "" // an accepted ASCII spelling, not a lookalike
	}
	for _, field := range envelopeTopFields {
		if strings.EqualFold(key, field) {
			return field
		}
	}
	return ""
}

// scanEnvelopeDuplicates tokenizes the committed envelope and rejects every
// repeated object key. The five known top-level fields are identified case-
// insensitively: two spellings that differ only in ASCII letter case (both
// keys already JSON-unescaped at this point) are the same field, in whatever
// order they appear and whether or not their values agree, so a later
// "CIRCUITS" or "FORMAT" can never override an earlier one through encoding/
// json's last-value-wins struct matching. Such a pair is reported as a
// duplicated top-level field named by its standard lowercase spelling.
//
// A non-ASCII spelling that folds onto a known field but is not an ASCII case
// variant ("circuitſ", "setupſ", "jobſ", "artifactſ" with U+017F long s,
// directly written or ſ-escaped) is rejected outright as data corruption:
// encoding/json would match it onto the field, so ignoring it as unknown
// could let its value replace the real one (an empty array hiding every
// record), and accepting it would let the records vanish on the next commit.
// The rule holds for the lookalike appearing alone — value a legal record, an
// empty array or null alike — and for it appearing beside the canonical
// spelling or an ASCII case variant, in either order and whether the values
// agree. The error names both the standard field and the actual spelling.
//
// Circuit, setup and job records are scanned one record at a time through
// their shared per-record readers — the record's own top-level keys are
// checked here (with the record's 1-based index, or the job's id, reported)
// by scanCircuitArray, scanSetupArray in setup_record.go and the shared job
// reader scanJobArray in job_record.go, while a nested value such as a
// constraint definition or an unknown member's object is skipped and left to
// its own strict decoder. Every other envelope member is scanned recursively
// so a duplicated key anywhere in committed data fails the read instead of
// silently resolving to its last value.
func scanEnvelopeDuplicates(raw []byte) error {
	dec := json.NewDecoder(bytes.NewReader(bytes.TrimSpace(raw)))
	dec.UseNumber()
	open, err := dec.Token()
	if err != nil || open != json.Delim('{') {
		return corruptf("data file envelope must be a JSON object")
	}
	// Exact spellings retain the pre-existing check for unknown keys;
	// canonical names remember a known field's first occurrence regardless
	// of the case it was written in.
	seenTop := make(map[string]bool)
	seenCanonical := make(map[string]bool)
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return corruptf("data file envelope is not valid JSON: %v", err)
		}
		key, ok := keyTok.(string)
		if !ok {
			return corruptf("data file envelope is not valid JSON")
		}
		// Reject a non-ASCII spelling that encoding/json's Unicode-folded tag
		// matching would read as a known field ("circuitſ" with long s,
		// directly written or ſ-escaped) before anything else. It is damage
		// even on its own and whatever its value — a legal record, an empty
		// array or null — and whether it precedes or follows the canonical or
		// an ASCII case-variant spelling: the read may neither ignore it as an
		// unknown member nor choose one of the values and carry on.
		if canonical := envelopeFieldLookalike(key); canonical != "" {
			return corruptf("data file envelope carries top-level field %q under non-ASCII spelling %q; such a lookalike spelling is data corruption",
				canonical, key)
		}
		if canonical := canonicalEnvelopeField(key); canonical != "" {
			if seenCanonical[canonical] {
				if key == canonical {
					return corruptf("data file envelope contains duplicate top-level field %q", canonical)
				}
				return corruptf("data file envelope contains duplicate top-level field %q (also present as %q)",
					canonical, key)
			}
			seenCanonical[canonical] = true
			if canonical == "circuits" {
				if err := scanCircuitArray(dec); err != nil {
					return err
				}
				continue
			}
			if canonical == "jobs" {
				if err := scanJobArray(dec); err != nil {
					return err
				}
				continue
			}
			if canonical == "setups" {
				if err := scanSetupArray(dec); err != nil {
					return err
				}
				continue
			}
			if err := skipValueWithDupKeys(dec, "data file envelope field "+strconv.Quote(canonical)); err != nil {
				return err
			}
			continue
		}
		if seenTop[key] {
			return corruptf("data file envelope contains duplicate field %q", key)
		}
		seenTop[key] = true
		if err := skipValueWithDupKeys(dec, "data file envelope field "+strconv.Quote(key)); err != nil {
			return err
		}
	}
	if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
		return corruptf("data file envelope is not valid JSON")
	}
	if _, err := dec.Token(); err != io.EOF {
		return corruptf("data file envelope is not valid JSON: trailing data after the object")
	}
	return nil
}

// skipValueWithDupKeys consumes one JSON value positioned at its first token,
// recursively rejecting duplicate object keys.
func skipValueWithDupKeys(dec *json.Decoder, what string) error {
	tok, err := dec.Token()
	if err != nil {
		return corruptf("%s is not valid JSON: %v", what, err)
	}
	delim, ok := tok.(json.Delim)
	if !ok {
		return nil // scalar (including null)
	}
	switch delim {
	case '{':
		seen := make(map[string]bool)
		for dec.More() {
			keyTok, err := dec.Token()
			if err != nil {
				return corruptf("%s is not valid JSON: %v", what, err)
			}
			key, ok := keyTok.(string)
			if !ok {
				return corruptf("%s is not valid JSON", what)
			}
			if seen[key] {
				return corruptf("%s contains duplicate field %q", what, key)
			}
			seen[key] = true
			if err := skipValueWithDupKeys(dec, what+" "+strconv.Quote(key)); err != nil {
				return err
			}
		}
		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
			return corruptf("%s is not valid JSON", what)
		}
	case '[':
		index := 0
		for dec.More() {
			index++
			if err := skipValueWithDupKeys(dec, fmt.Sprintf("%s element #%d", what, index)); err != nil {
				return err
			}
		}
		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
			return corruptf("%s is not valid JSON", what)
		}
	}
	return nil
}

type persistTerm struct {
	Wire  int    `json:"wire"`
	Coeff string `json:"coeff"`
}

type persistConstraint struct {
	A []persistTerm `json:"a"`
	B []persistTerm `json:"b"`
	C []persistTerm `json:"c"`
}

// persistDefinition is the canonical, already-validated constraint set bound
// to one circuit version. The public/private partition is owned by the
// circuit record and is deliberately not duplicated here, so it can never
// drift from the declared counts.
type persistDefinition struct {
	Modulus     string              `json:"modulus"`
	Constraints []persistConstraint `json:"constraints"`
}

// persistArtifact is a compiled artifact: the version's identity and
// constraint count bound to its recomputable SHA-256 hash.
type persistArtifact struct {
	Name        string `json:"name"`
	Version     int    `json:"version"`
	Modulus     int64  `json:"modulus"`
	Constraints int    `json:"constraints"`
	Hash        string `json:"hash"`
}

// Store is a persistent workbench backed by one local data directory.
//
// All operations are safe for concurrent use by multiple goroutines and by
// several processes pointed at the same directory: an in-process mutex plus a
// process-shared flock serialize commits, and every commit is an atomic
// temp-file/fsync/rename replacement. Open the directory with Open and call
// Close when done.
type Store struct {
	dir  string
	mu   sync.Mutex
	lock *os.File

	data envelope
}

// resolveDataDir turns the Open argument into the absolute physical
// directory the store will be permanently pinned to.
//
// The argument is resolved exactly the way the kernel reaches it on an
// open(2) — relative components anchored to the process's current working
// directory at Open time, one component at a time, every symlink expanded at
// the position where the walk meets it. No lexical Clean is applied first:
// filepath.Abs/Clean would fold "entry/.." before the symlink was ever
// examined, so a ".." standing after a symlink pops the link's resolved
// target rather than the link's own spelling, and a/link/../x cannot be made
// to name a/x and select another data directory. Any trailing segment that
// does not exist yet (a data directory to be created by Open, or a
// not-yet-existing parent) is appended verbatim to the resolved physical
// prefix, and MkdirAll creates it beneath that prefix; a ".." after such a
// missing component cannot be walked faithfully (the kernel reports ENOENT
// there instead of folding the literal path) and fails the resolution. A
// dangling entry link — the entry itself is a symlink whose target does not
// exist — resolves through the link target's spelling and is created there.
func resolveDataDir(dir string) (string, error) {
	resolved, err := resolveExistingPrefix(dir)
	if err != nil {
		return "", err
	}
	if !filepath.IsAbs(resolved) {
		// The walk itself stayed relative to the Open-time working directory;
		// only now, after every symlink has been expanded and every ".."
		// popped in walk order, anchor the result absolutely for pinning.
		resolved, err = filepath.Abs(resolved)
		if err != nil {
			return "", err
		}
	}
	return resolved, nil
}

// maxDataDirLinks bounds symlink expansion while resolving the data
// directory, matching the kernel's ELOOP guard: a link cycle must fail Open
// rather than loop forever.
const maxDataDirLinks = 255

// resolveExistingPrefix walks path the way a kernel path walk reaches it,
// accepting both absolute and Open-cwd-relative paths. Symlinks are expanded
// inline where the walk meets them and ".." pops the directory the walk is
// actually standing in (a link target, not the link spelling). Unlike
// filepath.EvalSymlinks the walk tolerates a missing tail: at the first
// component that cannot be Lstat'd, that component and the remaining literal
// components are appended to the resolved prefix so Open can create the chain
// with MkdirAll — unless the remainder contains "..", which could not be
// resolved against a non-existent entry and is an error.
func resolveExistingPrefix(path string) (string, error) {
	volLen := len(filepath.VolumeName(path))
	pathSeparator := string(os.PathSeparator)
	if volLen < len(path) && os.IsPathSeparator(path[volLen]) {
		volLen++
	}
	vol := path[:volLen] // "/" (or a drive/UNC root elsewhere); "" when relative
	dest := vol
	linksWalked := 0
	for start, end := volLen, volLen; start < len(path); start = end {
		for start < len(path) && os.IsPathSeparator(path[start]) {
			start++
		}
		end = start
		for end < len(path) && !os.IsPathSeparator(path[end]) {
			end++
		}
		if end == start {
			break
		}
		comp := path[start:end]
		if comp == "." {
			continue
		}
		if comp == ".." {
			// Pop what the walk has actually reached; symlinks have already
			// been expanded into dest, so this removes the target, never the
			// link spelling.
			r := -1
			for i := len(dest) - 1; i >= volLen; i-- {
				if os.IsPathSeparator(dest[i]) {
					r = i
					break
				}
			}
			if r < volLen || dest[r+1:] == ".." {
				if len(dest) > volLen {
					dest += pathSeparator
				}
				dest += ".."
			} else {
				dest = dest[:r]
			}
			continue
		}

		if len(dest) > len(filepath.VolumeName(dest)) && !os.IsPathSeparator(dest[len(dest)-1]) {
			dest += pathSeparator
		}
		dest += comp

		fi, err := os.Lstat(dest)
		if err != nil {
			if !os.IsNotExist(err) {
				return "", err
			}
			// Missing tail: append the remainder literally, refusing a
			// remainder containing ".." (unresolvable against this absent
			// entry), and let MkdirAll create the chain.
			for r := end; r < len(path); {
				for r < len(path) && os.IsPathSeparator(path[r]) {
					r++
				}
				s := r
				for r < len(path) && !os.IsPathSeparator(path[r]) {
					r++
				}
				switch path[s:r] {
				case "", ".":
				case "..":
					return "", fmt.Errorf("cannot resolve %q: %q does not exist and is followed by a parent reference", path, comp)
				default:
					dest += pathSeparator + path[s:r]
				}
			}
			return filepath.Clean(dest), nil
		}
		if fi.Mode()&os.ModeSymlink == 0 {
			if !fi.Mode().IsDir() && end < len(path) {
				return "", fmt.Errorf("cannot resolve %q: %q is not a directory", path, comp)
			}
			continue
		}
		linksWalked++
		if linksWalked > maxDataDirLinks {
			return "", fmt.Errorf("cannot resolve %q: too many symlinks", path)
		}
		link, err := os.Readlink(dest)
		if err != nil {
			return "", err
		}
		// Expand the link exactly at the walk position: the still-queued
		// components (including any "..") continue from the target rather
		// than from the link spelling.
		path = link + path[end:]
		switch {
		case len(link) > 0 && os.IsPathSeparator(link[0]):
			volLen = 1
			vol = path[:1]
			dest = vol
			end = 1
		default:
			if v := filepath.VolumeName(link); v != "" {
				if len(link) > len(v) && os.IsPathSeparator(link[len(v)]) {
					v += string(os.PathSeparator)
				}
				volLen = len(v)
				vol = v
				dest = vol
				end = volLen
				break
			}
			// Relative link: it names a path from the directory holding the
			// link, which is dest without the link's own component.
			r := -1
			for i := len(dest) - 1; i >= volLen; i-- {
				if os.IsPathSeparator(dest[i]) {
					r = i
					break
				}
			}
			if r < volLen {
				dest = vol
			} else {
				dest = dest[:r]
			}
			end = 0
		}
	}
	return filepath.Clean(dest), nil
}

// Open opens (creating if needed) the workbench data in dir. If the
// directory does not exist it is created. Existing committed data is loaded
// and fully validated before Open returns; on a corrupt, truncated or
// unsupported-format file Open returns an error wrapping ErrDataCorrupt and
// leaves every file in the directory untouched.
//
// dir is resolved against the process's current working directory at Open
// time and pinned for the store's lifetime: a relative path such as
// "bench-data" names one fixed directory from the moment Open succeeds, and
// later working-directory changes never redirect the store's reads, writes,
// lock or Dir to another location.
//
// The pinning is to the actual directory opened, not to the literal path
// spelling: symlinks already present in the file system — whether dir itself
// is a link or one of its parent directories is — are resolved segment by
// segment at Open time, and Dir reports the resulting absolute physical
// directory. Repointing or removing an entry link afterwards never moves the
// store: queries, commits, the lock file and compiled-artifact bindings keep
// using the original directory even after the link changes or vanishes. A
// ".." following a symlink is resolved the way the kernel walk reaches it
// (the already-resolved link target is popped), never by lexical folding of
// the literal path, so it cannot select a different data directory. A
// not-yet-existing data directory named through a valid (possibly
// symlinked) parent is created under the parent's physical location. Paths
// to constraint definitions and input files passed to individual operations
// are not pinned this way — they keep being resolved against the caller's
// working directory at call time.
func Open(dir string) (*Store, error) {
	if dir == "" {
		return nil, invalidf("data directory must not be empty")
	}
	// Resolve and pin the physical location now, before anything else can
	// change. resolveDataDir walks the argument the way the kernel reaches
	// it — relative to the process working directory at Open time, symlinks
	// expanded segment by segment in walk order and ".." popped in place — so
	// a later chdir, a repointed or deleted entry link, or a ".." sitting
	// after a symlink cannot move reads, writes, the lock or Dir onto another
	// directory. The result is absolute and names the real directory opened.
	dir, err := resolveDataDir(dir)
	if err != nil {
		return nil, fmt.Errorf("cannot resolve data directory %q: %w", dir, err)
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, fmt.Errorf("cannot create data directory %q: %w", dir, err)
	}
	lockPath := filepath.Join(dir, dirLockFile)
	lock, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o644)
	if err != nil {
		return nil, fmt.Errorf("cannot open lock file in %q: %w", dir, err)
	}
	// Serialize against other processes while we read / validate.
	if err := lockExclusive(lock); err != nil {
		lock.Close()
		return nil, fmt.Errorf("cannot lock data directory %q: %w", dir, err)
	}

	s := &Store{dir: dir, lock: lock}
	if err := s.loadLocked(); err != nil {
		unlockLock(lock)
		lock.Close()
		return nil, err
	}
	// The lock is taken again per operation; holding it for the store's
	// lifetime would forbid two open handles on one directory.
	if err := unlockLock(lock); err != nil {
		lock.Close()
		return nil, fmt.Errorf("cannot release open lock on %q: %w", dir, err)
	}
	return s, nil
}

// Close releases the directory lock. It does not discard committed data.
func (s *Store) Close() error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.lock == nil {
		return nil
	}
	var first error
	if err := unlockLock(s.lock); err != nil {
		first = err
	}
	if err := s.lock.Close(); err != nil && first == nil {
		first = err
	}
	s.lock = nil
	return first
}

// Dir reports the data directory backing the store.
func (s *Store) Dir() string { return s.dir }

func (s *Store) dataPath() string { return filepath.Join(s.dir, dirDataFile) }
func (s *Store) tmpPath() string  { return filepath.Join(s.dir, dirTmpFile) }

// loadLocked reads and validates the committed file. Caller must hold the
// exclusive flock; the in-process mutex is taken by the public Open path.
func (s *Store) loadLocked() error {
	raw, err := os.ReadFile(s.dataPath())
	if errors.Is(err, os.ErrNotExist) {
		s.data = envelope{Format: FormatVersion}
		return nil
	}
	if err != nil {
		return fmt.Errorf("cannot read data file %q: %w", s.dataPath(), err)
	}
	if len(strings.TrimSpace(string(raw))) == 0 {
		return corruptf("data file %q is empty or truncated; refusing to treat it as a new directory", s.dataPath())
	}

	var env envelope
	if err := json.Unmarshal(raw, &env); err != nil {
		// Shape failures surfaced by the persisted-definition decoders are
		// integrity failures, not JSON syntax errors; report their detail
		// instead of the generic "not valid JSON" wording.
		var se StoreError
		if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
			return corruptf("data file %q failed integrity validation: %s; original file left in place", s.dataPath(), se.Detail)
		}
		return corruptf("data file %q is not valid JSON (%v); original file left in place", s.dataPath(), err)
	}
	if env.Format == 0 {
		return corruptf("data file %q has no format version; original file left in place", s.dataPath())
	}
	if env.Format != FormatVersion {
		return corruptf("data file %q uses unsupported format version %d (this build supports %d); original file left in place",
			s.dataPath(), env.Format, FormatVersion)
	}
	if err := validateEnvelope(env); err != nil {
		return corruptf("data file %q failed integrity validation: %v; original file left in place", s.dataPath(), err)
	}
	s.data = env
	return nil
}

// commitLocked writes the pending state atomically: temp file → fsync →
// rename → fsync directory. Caller must hold both the in-process mutex and
// the exclusive flock; all in-memory mutations must already have happened and
// been rule-checked, so a failure here occurs before any success is reported.
func (s *Store) commitLocked() error {
	s.data.Format = FormatVersion
	// Stable output: records are stored sorted so files are deterministic.
	sortEnvelope(&s.data)

	payload, err := json.MarshalIndent(&s.data, "", "  ")
	if err != nil {
		return fmt.Errorf("cannot encode data: %w", err)
	}
	payload = append(payload, '\n')

	tmp := s.tmpPath()
	f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o644)
	if err != nil {
		return fmt.Errorf("cannot stage write in %q: %w", s.dir, err)
	}
	if _, err := f.Write(payload); err != nil {
		f.Close()
		os.Remove(tmp)
		return fmt.Errorf("cannot write staged data: %w", err)
	}
	if err := f.Sync(); err != nil {
		f.Close()
		os.Remove(tmp)
		return fmt.Errorf("cannot flush staged data: %w", err)
	}
	if err := f.Close(); err != nil {
		os.Remove(tmp)
		return fmt.Errorf("cannot finish staged data: %w", err)
	}
	if err := os.Rename(tmp, s.dataPath()); err != nil {
		os.Remove(tmp)
		return fmt.Errorf("cannot commit data file: %w", err)
	}
	if err := syncDir(s.dir); err != nil {
		// The rename already happened; lack of dir fsync only weakens crash
		// durability, never correctness of what is visible now.
		return nil
	}
	return nil
}

// withLock runs fn under the in-process mutex and an exclusive flock, then
// atomically commits when fn requests it. The on-disk state is re-read after
// acquiring the lock, so concurrent commits from another process or another
// handle are always observed. Operations validate before mutating; a rejected
// operation (commit=false or an error) writes nothing and leaves committed
// state unchanged.
func (s *Store) withLock(fn func() (commit bool, err error)) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.lock == nil {
		return invalidf("store is closed")
	}
	if err := lockExclusive(s.lock); err != nil {
		return fmt.Errorf("cannot lock data directory: %w", err)
	}
	defer unlockLock(s.lock)

	if err := s.loadLocked(); err != nil {
		return err
	}
	commit, err := fn()
	if err != nil {
		return err
	}
	if !commit {
		return nil
	}
	return s.commitLocked()
}

// withLockRead runs fn under a shared flock over freshly reloaded state.
func (s *Store) withLockRead(fn func() error) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.lock == nil {
		return invalidf("store is closed")
	}
	if err := lockShared(s.lock); err != nil {
		return fmt.Errorf("cannot lock data directory: %w", err)
	}
	defer unlockLock(s.lock)
	if err := s.loadLocked(); err != nil {
		return err
	}
	return fn()
}

func sortEnvelope(env *envelope) {
	sort.Slice(env.Circuits, func(i, j int) bool {
		if env.Circuits[i].Name != env.Circuits[j].Name {
			return env.Circuits[i].Name < env.Circuits[j].Name
		}
		return env.Circuits[i].Version < env.Circuits[j].Version
	})
	sort.Slice(env.Setups, func(i, j int) bool {
		if env.Setups[i].Name != env.Setups[j].Name {
			return env.Setups[i].Name < env.Setups[j].Name
		}
		return env.Setups[i].Version < env.Setups[j].Version
	})
	sort.Slice(env.Jobs, func(i, j int) bool { return env.Jobs[i].ID < env.Jobs[j].ID })
	sort.Slice(env.Artifacts, func(i, j int) bool {
		if env.Artifacts[i].Name != env.Artifacts[j].Name {
			return env.Artifacts[i].Name < env.Artifacts[j].Name
		}
		return env.Artifacts[i].Version < env.Artifacts[j].Version
	})
}

// validateEnvelope re-checks every invariant on load so a tampered or
// hand-edited file cannot bypass the domain rules.
//
// A stored constraint definition is parsed and canonicalized exactly once
// per load: the circuit pass validates every defined version against its
// declared counts and keeps the resulting canonical form, and the artifact
// pass reuses that same form to verify the recorded modulus, constraint
// count and hash. The map is built fresh on each call, so the reuse never
// carries a judgment across loads — every read validates the bytes found on
// disk at that moment.
func validateEnvelope(env envelope) error {
	seenCircuit := make(map[[2]string]bool)
	circuitOK := make(map[[2]string]bool)
	canonicalDefs := make(map[[2]string]*canonicalDefinition)
	for i, c := range env.Circuits {
		key := [2]string{c.Name, itoa(c.Version)}
		if c.Name == "" || strings.TrimSpace(c.Name) == "" {
			return fmt.Errorf("circuit #%d has an empty or blank name", i+1)
		}
		if c.Version <= 0 {
			return fmt.Errorf("circuit %q version %d is not a positive integer", c.Name, c.Version)
		}
		if seenCircuit[key] {
			return fmt.Errorf("circuit %q version %d appears more than once", c.Name, c.Version)
		}
		seenCircuit[key] = true
		if c.Constraints <= 0 {
			return fmt.Errorf("circuit %q v%d: constraints must be > 0", c.Name, c.Version)
		}
		if c.PublicInputs < 0 || c.PrivateInputs < 0 {
			return fmt.Errorf("circuit %q v%d: input counts must not be negative", c.Name, c.Version)
		}
		// The same representability rule the write path enforces: wire 0 plus
		// every declared input must fit inside the platform's int. A record
		// beyond that bound can never have been written by this build and
		// cannot be checked safely, so the directory is corrupt rather than
		// silently narrowed or read with a wrapped-around layout.
		if !inputLayoutRepresentable(c.PublicInputs, c.PrivateInputs) {
			return fmt.Errorf("circuit %q v%d: input layout is not representable: 1 constant wire + %d public + %d private inputs exceeds the platform limit of %d wires",
				c.Name, c.Version, c.PublicInputs, c.PrivateInputs, maxInputWires)
		}
		if c.Definition != nil {
			def, err := validatePersistDefinition(c.Name, c.Version, c.Constraints, c.PublicInputs, c.PrivateInputs, c.Definition)
			if err != nil {
				return err
			}
			canonicalDefs[key] = def
		}
		circuitOK[key] = true
	}
	seenSetup := make(map[[2]string]bool)
	for i, p := range env.Setups {
		key := [2]string{p.Name, itoa(p.Version)}
		if !circuitOK[key] {
			return fmt.Errorf("setup #%d belongs to unknown circuit %q v%d", i+1, p.Name, p.Version)
		}
		c := findPersistCircuit(env.Circuits, p.Name, p.Version)
		if c == nil || !c.Frozen {
			return fmt.Errorf("setup belongs to non-frozen circuit %q v%d", p.Name, p.Version)
		}
		if seenSetup[key] {
			return fmt.Errorf("setup for %q v%d appears more than once", p.Name, p.Version)
		}
		seenSetup[key] = true
	}
	seenJob := make(map[string]bool)
	for i, j := range env.Jobs {
		if j.ID == "" || strings.TrimSpace(j.ID) == "" {
			return fmt.Errorf("job #%d has an empty or blank id", i+1)
		}
		if seenJob[j.ID] {
			return fmt.Errorf("job %q appears more than once", j.ID)
		}
		seenJob[j.ID] = true
		if j.Kind != "prove" {
			return fmt.Errorf("job %q has unsupported kind %q", j.ID, j.Kind)
		}
		if j.Attempt <= 0 {
			return fmt.Errorf("job %q: attempt must be a positive integer", j.ID)
		}
		key := [2]string{j.Circuit, itoa(j.Version)}
		if !circuitOK[key] {
			return fmt.Errorf("job %q binds to unknown circuit %q v%d", j.ID, j.Circuit, j.Version)
		}
		c := findPersistCircuit(env.Circuits, j.Circuit, j.Version)
		if c == nil || !c.Frozen {
			return fmt.Errorf("job %q binds to non-frozen circuit %q v%d", j.ID, j.Circuit, j.Version)
		}
		if !seenSetup[key] {
			return fmt.Errorf("job %q binds to circuit %q v%d without a trusted setup", j.ID, j.Circuit, j.Version)
		}
		// A recorded compiled-artifact binding must still resolve against the
		// pinned version's artifact; a dangling or mismatched binding makes
		// the file unreadable rather than silently dropping the binding.
		if j.CompiledHash != "" {
			artifact := findArtifact(env.Artifacts, j.Circuit, j.Version)
			if artifact == nil {
				return fmt.Errorf("job %q binds to compiled artifact of %q v%d which is missing", j.ID, j.Circuit, j.Version)
			}
			if artifact.Hash != j.CompiledHash {
				return fmt.Errorf("job %q compiled hash %q does not match the artifact of %q v%d (hash %q)",
					j.ID, j.CompiledHash, j.Circuit, j.Version, artifact.Hash)
			}
		}
	}
	seenArtifact := make(map[[2]string]bool)
	for i, a := range env.Artifacts {
		key := [2]string{a.Name, itoa(a.Version)}
		if !circuitOK[key] {
			return fmt.Errorf("artifact #%d belongs to unknown circuit %q v%d", i+1, a.Name, a.Version)
		}
		c := findPersistCircuit(env.Circuits, a.Name, a.Version)
		if c == nil || !c.Frozen {
			return fmt.Errorf("artifact belongs to non-frozen circuit %q v%d", a.Name, a.Version)
		}
		if seenArtifact[key] {
			return fmt.Errorf("artifact for %q v%d appears more than once", a.Name, a.Version)
		}
		seenArtifact[key] = true
		if c.Definition == nil {
			return fmt.Errorf("artifact for %q v%d has no constraint definition", a.Name, a.Version)
		}
		if a.Constraints != c.Constraints {
			return fmt.Errorf("artifact for %q v%d constraint count %d disagrees with the version's %d",
				a.Name, a.Version, a.Constraints, c.Constraints)
		}
		// The circuit pass above already validated and canonicalized this
		// version's definition (every artifact requires a defined version,
		// checked just above), so the artifact check reuses that one result
		// instead of re-parsing and re-normalizing the same stored definition.
		def := canonicalDefs[key]
		if int64(a.Modulus) != def.modulus || len(def.constraints) != a.Constraints {
			return fmt.Errorf("artifact for %q v%d is inconsistent with its stored definition", a.Name, a.Version)
		}
		wantHash := artifactHash(a.Name, a.Version, def)
		if a.Hash != wantHash {
			return fmt.Errorf("artifact for %q v%d hash %q does not recompute from the definition (want %q)",
				a.Name, a.Version, a.Hash, wantHash)
		}
	}
	return nil
}

// validatePersistDefinition re-validates a stored definition against its
// version's declared counts: prime modulus, in-range wires and an exact
// constraint count match. On success it returns the canonical form built
// during validation, so a later check against the same version's artifact
// reuses it instead of parsing and normalizing the definition a second time.
func validatePersistDefinition(name string, version, constraints, public, private int, def *persistDefinition) (*canonicalDefinition, error) {
	parsed, err := definitionFromPersist(*def, public, private)
	if err != nil {
		return nil, fmt.Errorf("circuit %q v%d has a corrupt constraint definition: %w", name, version, err)
	}
	if !parsed.compatibleWith(constraints, public, private) {
		return nil, fmt.Errorf("circuit %q v%d definition is incompatible with its declared counts", name, version)
	}
	return parsed, nil
}

func findPersistCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
	for i := range cs {
		if cs[i].Name == name && cs[i].Version == version {
			return &cs[i]
		}
	}
	return nil
}

func itoa(v int) string { return fmt.Sprintf("%d", v) }

package zkcircuit

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"sort"
	"strconv"
	"strings"
)

// Saved proof-job records used to be read and field-checked twice: once while
// the committed envelope was tokenized to reject a repeated object key
// (scanJobArray) and again while each jobs element was decoded into a
// persistJob (persistJob.UnmarshalJSON). Each pass gathered the record's
// member keys on its own and carried its own copy of the pinned-version and
// compiled-binding spelling rules, so the rule for naming a job, pinning a
// version or reading the optional compiled hash lived in two places that had
// to agree by construction.
//
// This file is now the single home of a saved job's reading and validation
// rules: the persistJob shape, the accepted spellings of its named fields
// (id / circuit / version / compiled_hash), the id exact-readback rule, the
// owning-circuit and pinned-version uniqueness rules and the compiled-binding
// duplicate/lookalike/type rules, together with one per-record reading engine (readJobRecord) both read passes drive. The
// directory scan and the single-record decode hence tokenize one record once
// and judge its keys and structure through the same code, which also covers
// two byte-identical member keys — a case a post-decode member map could not
// see on its own.
//
// Only the reading of saved jobs is consolidated here. The public behavior —
// which values load, which are refused, how the failure is located and in
// what order findings surface — is unchanged; the commit and query entry
// points and the on-disk format stay as they were. In particular the two read
// passes keep their historical division of labor and precedence because an
// open always runs the directory scan before the typed decode: the scan owns
// structural findings, the job-id, pinned-version and owning-circuit
// ambiguities, exact repeated keys and nested repeated keys
// (jobRecordScan.judge), while the typed decode owns the
// binding-field lookalike, duplicate-binding and binding-value-type findings
// plus the ordinary struct decode (decodeJob).

type persistJob struct {
	ID       string `json:"id"`
	Circuit  string `json:"circuit"`
	Version  int    `json:"version"`
	Kind     string `json:"kind"`
	Attempt  int    `json:"attempt"`
	Artifact string `json:"artifact,omitempty"`
	// CompiledHash is the optional binding to the pinned version's compiled
	// artifact, stored exactly as submitted.
	CompiledHash string `json:"compiled_hash,omitempty"`
}

// The canonical spellings of the job-record fields the read path treats by
// rule rather than leaving entirely to a plain struct decode. Keys reach
// every rule below already JSON-unescaped, so a key written with a \uXXXX
// escape is judged on its decoded spelling too.
const (
	jobIDKey        = "id"
	jobCircuitKey   = "circuit"
	jobVersionKey   = "version"
	compiledHashKey = "compiled_hash"
)

// isASCIIFoldOf reports whether key names canonical under an ASCII-only
// letter-case fold: the two must have the same byte length and every byte
// must match after mapping A-Z onto a-z. A key of a different length, or one
// that needs a non-ASCII rune to match, returns false — use strings.EqualFold
// to detect those non-ASCII lookalikes separately.
func isASCIIFoldOf(key, canonical string) bool {
	if len(key) != len(canonical) {
		return false
	}
	for i := 0; i < len(key); i++ {
		c := key[i]
		if c >= 'A' && c <= 'Z' {
			c += 'a' - 'A'
		}
		if c != canonical[i] {
			return false
		}
	}
	return true
}

// isJobVersionKey reports whether key names a job record's pinned circuit
// version field under any spelling the ordinary decode fills Version from:
// canonical "version", an ASCII letter-case variant such as "VERSION" or
// "VeRsIoN", or a JSON-escaped spelling that unescapes onto either. Because
// encoding/json's struct-tag matching folds with Unicode case rules
// (strings.EqualFold), the long-s "verſion" (U+017F, written directly or as
// the u017f escape) names the field too.
func isJobVersionKey(key string) bool {
	return strings.EqualFold(key, jobVersionKey)
}

// isJobCircuitKey reports whether key names a job record's owning circuit
// field under any spelling the ordinary decode fills Circuit from: canonical
// "circuit" or an ASCII letter-case variant such as "CIRCUIT" or "CiRcUiT",
// including a JSON-escaped spelling that unescapes onto either (keys arrive
// here already unescaped). No non-ASCII rune case-folds onto any letter of
// "circuit", so the ASCII fold and encoding/json's Unicode-folded tag
// matching recognize exactly the same keys for this field.
func isJobCircuitKey(key string) bool {
	return isASCIIFoldOf(key, jobCircuitKey)
}

// isJobIDKey reports whether key names a job record's identity field under
// any spelling the ordinary decode fills ID from: canonical "id" and the
// ASCII letter-case variants "ID", "Id", "iD", including a JSON-escaped
// spelling that unescapes onto one of them (keys arrive here already
// unescaped). "id" is two ASCII letters, so no non-ASCII rune case-folds
// onto either letter and the ASCII fold recognizes exactly the keys
// encoding/json's Unicode-folded tag matching binds to the field.
func isJobIDKey(key string) bool {
	return isASCIIFoldOf(key, jobIDKey)
}

// isCompiledHashKey reports whether key is an accepted spelling of the
// compiled-artifact binding field: only "compiled_hash" itself and ASCII
// letter-case variants such as "COMPILED_HASH" or "CoMpIlEd_HaSh". Non-ASCII
// letters are never folded here; compiledHashLookalike rejects those.
func isCompiledHashKey(key string) bool {
	return isASCIIFoldOf(key, compiledHashKey)
}

// rejectAmbiguousJobID enforces the identity uniqueness rule shared by the
// directory scan and the single-record decode (both drive readJobRecord):
// the id is a job's sole, deterministic identity — the key a query uses to
// find the record — so one record may carry the field under at most one
// recognized spelling (isJobIDKey): canonical "id", the ASCII letter-case
// variants "ID", "Id", "iD", or a JSON-escaped spelling that unescapes onto
// one of them. Two spellings on one record make the job's identity depend on
// key order, since encoding/json keeps the last value, and corrupt the read:
// the whole record is refused whether the values agree or differ, whether
// both are present, non-empty and legal ids, and whether unrelated members
// (the circuit name, the pinned version, the attempt count, …) sit between
// them — neither value is ever picked to carry on, and swapping the two keys
// never changes the refusal or moves the query id. A record carrying only
// case variants with no lowercase "id" ("ID" beside "Id", …) is refused on
// the same terms: the pair still names one field twice. Two byte-identical
// spellings are covered too. A single spelling of any recognized kind is the
// one id field and keeps its current reading: the value is matched exactly
// as written, with no case folding, space trimming or U+FFFD repair.
//
// keys are the record's member keys in any order; the recognized spellings
// are filtered and sorted here so the message is deterministic. where names
// the record positionally — the record has more than one id, so no candidate
// value may be treated as its settled identity.
func rejectAmbiguousJobID(where string, keys []string) error {
	var idKeys []string
	for _, key := range keys {
		if isJobIDKey(key) {
			idKeys = append(idKeys, key)
		}
	}
	if len(idKeys) <= 1 {
		return nil
	}
	sort.Strings(idKeys)
	quoted := make([]string, len(idKeys))
	for i, k := range idKeys {
		quoted[i] = strconv.Quote(k)
	}
	return corruptf("%s carries the job id field %q more than once (as %s)",
		where, jobIDKey, strings.Join(quoted, ", "))
}

// rejectAmbiguousJobVersion enforces the pinned-version uniqueness rule shared
// by the directory scan and the single-record decode (both drive readJobRecord):
// the version a job writes is the sole authority for which frozen circuit — and
// therefore which trusted setup and compiled artifact — the job belongs to, so
// one record may carry the field under at most one recognized spelling
// (isJobVersionKey). Two spellings on one record make the bound version depend
// on key order, since encoding/json keeps the last value, and corrupt the read:
// the whole record is refused whether the values agree or differ, whether both
// are legal versions, and whether unrelated members sit between them — neither
// value is ever picked to carry on. A single spelling of any recognized kind —
// including a lone long-s "verſion" — is the one version field and keeps its
// current reading.
//
// keys are the record's member keys in any order; the recognized spellings are
// filtered and sorted here so the message is deterministic. where names the
// record exactly as the calling read path already located it (by id when the
// scan read one, else by position), so both paths name the problem the same
// way.
func rejectAmbiguousJobVersion(where string, keys []string) error {
	var versionKeys []string
	for _, key := range keys {
		if isJobVersionKey(key) {
			versionKeys = append(versionKeys, key)
		}
	}
	if len(versionKeys) <= 1 {
		return nil
	}
	sort.Strings(versionKeys)
	quoted := make([]string, len(versionKeys))
	for i, k := range versionKeys {
		quoted[i] = strconv.Quote(k)
	}
	return corruptf("%s carries the pinned version field %q more than once (as %s)",
		where, jobVersionKey, strings.Join(quoted, ", "))
}

// rejectAmbiguousJobCircuit enforces the owning-circuit uniqueness rule shared
// by the directory scan and the single-record decode (both drive readJobRecord):
// the circuit a job names is the sole authority for which circuit the job
// belongs to — and therefore which frozen version, trusted setup and compiled
// artifact it is read against — so one record may carry the field under at
// most one recognized spelling (isJobCircuitKey). Two spellings on one record
// make the owning circuit depend on key order, since encoding/json keeps the
// last value, and corrupt the read: the whole record is refused whether the
// values agree or differ, whether both name legal circuits, and whether
// unrelated members (the version, the attempt count, …) sit between them —
// neither value is ever picked to carry on, and swapping the two keys never
// changes the refusal. A single spelling of any recognized kind is the one
// circuit field and keeps its current reading: the value is matched against
// circuit names exactly as written, with no case folding or space trimming.
//
// keys are the record's member keys in any order; the recognized spellings are
// filtered and sorted here so the message is deterministic. where names the
// record exactly as the calling read path already located it (by id when the
// scan read one, else by position), so both paths name the problem the same
// way.
func rejectAmbiguousJobCircuit(where string, keys []string) error {
	var circuitKeys []string
	for _, key := range keys {
		if isJobCircuitKey(key) {
			circuitKeys = append(circuitKeys, key)
		}
	}
	if len(circuitKeys) <= 1 {
		return nil
	}
	sort.Strings(circuitKeys)
	quoted := make([]string, len(circuitKeys))
	for i, k := range circuitKeys {
		quoted[i] = strconv.Quote(k)
	}
	return corruptf("%s carries the circuit field %q more than once (as %s)",
		where, jobCircuitKey, strings.Join(quoted, ", "))
}

// compiledHashLookalike reports a member key encoding/json would match onto
// the binding field's struct tag yet which is not an accepted ASCII spelling
// (isCompiledHashKey). Struct-tag matching in encoding/json folds with the
// Unicode simple case-folding rules, so a non-ASCII lookalike —
// "compiled_haſh" with U+017F long s, whether written directly or as the
// JSON escape u017f — silently fills CompiledHash and would let a damaged
// binding (null above all) read as unbound, then vanish on the next commit.
// Such a key is damage, regardless of its value or of a correctly spelled
// sibling key being present. Several aliases are reported in lexicographic
// order so the message is stable.
func compiledHashLookalike(keys []string) string {
	var aliases []string
	for _, key := range keys {
		if isCompiledHashKey(key) {
			continue
		}
		if strings.EqualFold(key, compiledHashKey) {
			aliases = append(aliases, key)
		}
	}
	if len(aliases) == 0 {
		return ""
	}
	sort.Strings(aliases)
	return aliases[0]
}

// jobMember is one member of a saved job record as seen during the single
// per-record pass: its already-unescaped key and its raw value.
type jobMember struct {
	key   string
	value json.RawMessage
}

// jobRecordScan is the one read of one saved job record. Both read passes —
// the envelope-wide duplicate-key scan (scanJobArray) and the typed decode
// (decodeJob) — build one through readJobRecord. It records only what the
// shared rules need: the members in document order (exact spelling), the
// first member key repeated under that same exact spelling, the best-effort
// id used to name the record, any duplicate key nested inside a member's
// own object/array value, and any exact-readback damage to the id token
// (invalid UTF-8 bytes or an unpaired \uXXXX surrogate). Turning the members
// into a typed persistJob is left to the ordinary struct decode, which runs
// once afterwards.
type jobRecordScan struct {
	positional    string
	members       []jobMember
	dupKey        string
	id            string
	nestedErr     error
	idEncodingErr error
}

// scanName locates the record for a directory-scan finding: by its id when an
// exact "id" spelling held a legible, reliably readable string, else by its
// 1-based position. The id probe is deliberately exact — an "ID" case
// variant is not the id for scan attribution — and is best-effort: a missing,
// non-string or undecodable id, or one whose bytes encoding/json would repair
// on decode (invalid UTF-8, an unpaired surrogate), leaves the positional
// name, since such an id cannot be recovered to quote faithfully.
func (r *jobRecordScan) scanName() string {
	if r.id != "" && r.idEncodingErr == nil {
		return fmt.Sprintf("stored job record %q", r.id)
	}
	return r.positional
}

func (r *jobRecordScan) memberKeys() []string {
	keys := make([]string, 0, len(r.members))
	for _, m := range r.members {
		keys = append(keys, m.key)
	}
	return keys
}

func (r *jobRecordScan) valueOf(key string) json.RawMessage {
	for _, m := range r.members {
		if m.key == key {
			return m.value
		}
	}
	return nil
}

// bindingKeys lists the record's accepted compiled_hash spellings (canonical
// and ASCII case variants), in document order.
func (r *jobRecordScan) bindingKeys() []string {
	var keys []string
	for _, m := range r.members {
		if isCompiledHashKey(m.key) {
			keys = append(keys, m.key)
		}
	}
	return keys
}

// readJobRecord consumes exactly one job record value the decoder is
// positioned at — including its opening token — and returns the single scan.
// Every token is consumed whether or not the record is damaged. A null
// element or a non-object element is structural damage named by positional.
// positional is the name used when no legible id is read: the directory scan
// passes "job record #<1-based index>", the typed decode passes
// "stored job record".
func readJobRecord(dec *json.Decoder, positional string) (*jobRecordScan, error) {
	open, err := dec.Token()
	if err != nil {
		return nil, corruptf("%s is not valid JSON: %v", positional, err)
	}
	if open == nil {
		return nil, corruptf("%s must be a JSON object, not null", positional)
	}
	if open != json.Delim('{') {
		return nil, corruptf("%s must be a JSON object", positional)
	}

	r := &jobRecordScan{positional: positional}
	seenExact := make(map[string]bool)
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return nil, corruptf("%s is not valid JSON: %v", positional, err)
		}
		key, ok := keyTok.(string)
		if !ok {
			return nil, corruptf("%s is not valid JSON", positional)
		}
		// Consume the whole value first; the judgments below use only the key
		// (and, for the id probe, the already-captured bytes). Job members are
		// scalars, but an unknown member may carry an object/array whose own
		// duplicate keys must still fail the read.
		var value json.RawMessage
		if err := dec.Decode(&value); err != nil {
			return nil, corruptf("%s is not valid JSON: %v", positional, err)
		}
		// The id is the job's identity and must read back exactly as the
		// bytes on disk carry it. encoding/json silently rewrites invalid
		// UTF-8 bytes and unpaired \uXXXX surrogate escapes to U+FFFD, so the
		// raw token of every spelling the ordinary decode fills ID from
		// (isJobIDKey: canonical "id" and the ASCII case variants "ID",
		// "Id", "iD") is judged after the read. The exact "id" token also
		// supplies the best-effort name used to locate the record. A
		// non-string value (null, a number …) is left to the ordinary
		// decode's own failure: the encoding walk below is defined only over
		// one complete JSON string token.
		isIDSpelling := isJobIDKey(key)
		if isIDSpelling && bytes.HasPrefix(bytes.TrimSpace(value), []byte{'"'}) {
			if key == jobIDKey {
				if idVal, ierr := storedRecordShape.string(value, positional+` field "id"`); ierr == nil {
					r.id = idVal
				}
			}
			// The field is always quoted by its canonical name "id" in the
			// diagnostic, whatever accepted spelling the damaged token was
			// written under (an "ID" variant, a \uXXXX-escaped key).
			if r.idEncodingErr == nil {
				r.idEncodingErr = checkStoredStringEncoding(value,
					positional+` field "id"`, "committed job id")
			}
		}
		if seenExact[key] && r.dupKey == "" {
			r.dupKey = key
		}
		seenExact[key] = true
		r.members = append(r.members, jobMember{key: key, value: value})
		trimmed := bytes.TrimSpace(value)
		if r.nestedErr == nil && len(trimmed) > 0 && (trimmed[0] == '{' || trimmed[0] == '[') {
			nd := json.NewDecoder(bytes.NewReader(trimmed))
			r.nestedErr = skipValueWithDupKeys(nd, positional+" field "+strconv.Quote(key))
		}
	}
	if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
		return nil, corruptf("%s is not valid JSON", positional)
	}
	return r, nil
}

// judge applies the findings the directory scan owns, in the order they
// surface:
//
//  1. two recognized spellings of the job id field — equal or differing
//     values, both present and legal, even with unrelated members interleaved
//     and even with no lowercase "id" among them — so the job's identity is
//     never chosen by key order; this finding names the record positionally
//     (r.positional), never by a candidate id, because the record itself
//     refuses to settle which value that is;
//  2. two recognized spellings of the pinned version field — equal or
//     differing values, both legal, even with unrelated members interleaved —
//     so the bound version is never chosen by key order;
//  3. two recognized spellings of the owning circuit field, under the same
//     rule — the circuit a job belongs to is never chosen by key order;
//  4. an exact repeated member key (the first such key in document order,
//     including two byte-identical keys a member map could not retain);
//  5. a duplicate key nested inside a member's own object/array value;
//  6. an id token that would not read back unchanged — invalid UTF-8 bytes
//     or an unpaired surrogate escape under the canonical "id" or any ASCII
//     case spelling of it — so a saved job can never be re-read under a
//     U+FFFD-repaired identity; the record is located positionally when the
//     id itself cannot be recovered faithfully.
//
// The binding-field lookalike, duplicate-binding and binding-value-type rules
// are deliberately not here: the typed decode (which runs after the scan) owns
// those, so the historical precedence — every scan finding outranking every
// binding finding — is preserved when several problems coexist.
func (r *jobRecordScan) judge(where string) error {
	if err := rejectAmbiguousJobID(r.positional, r.memberKeys()); err != nil {
		return err
	}
	if err := rejectAmbiguousJobVersion(where, r.memberKeys()); err != nil {
		return err
	}
	if err := rejectAmbiguousJobCircuit(where, r.memberKeys()); err != nil {
		return err
	}
	if r.dupKey != "" {
		return corruptf("%s contains duplicate field %q", where, r.dupKey)
	}
	if r.nestedErr != nil {
		return r.nestedErr
	}
	if r.idEncodingErr != nil {
		return r.idEncodingErr
	}
	return nil
}

// scanJobArray consumes one "jobs" value positioned at its opening bracket and
// reads every record through the shared per-record engine, judging each before
// moving on. It is the directory-read counterpart of decodeJob and exists so a
// structural problem inside one job is attributed to that job — by its id when
// the id is a legible string that reads back unchanged, else by its 1-based
// position — rather than to an opaque "jobs" element index. A null array
// stays the pre-existing "no jobs" reading.
func scanJobArray(dec *json.Decoder) error {
	tok, err := dec.Token()
	if err != nil {
		return corruptf("data file envelope field \"jobs\" is not valid JSON: %v", err)
	}
	if tok == nil { // null: json.Unmarshal would produce no jobs
		return nil
	}
	if tok != json.Delim('[') {
		return corruptf("data file envelope field \"jobs\" must be an array")
	}
	index := 0
	for dec.More() {
		index++
		r, err := readJobRecord(dec, fmt.Sprintf("job record #%d", index))
		if err != nil {
			return err
		}
		if err := r.judge(r.scanName()); err != nil {
			return err
		}
	}
	if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
		return corruptf("data file envelope field \"jobs\" is not valid JSON")
	}
	return nil
}

// Strict decoding of a committed job record, including its identity id and its
// compiled-artifact binding.
//
// The id is the job's identity and is held to the same exact-readback rule as
// a circuit's name: its raw JSON string token must denote its value exactly —
// valid UTF-8 in its literal portions and no unpaired \uXXXX surrogate
// escapes under any spelling the ordinary decode fills ID from (canonical
// "id" and ASCII case variants such as "ID", a JSON-escaped spelling of
// either included). Both damage shapes decode to U+FFFD under encoding/json,
// so the job would read back under a repaired identity — a follow-up GetJob
// by the submitted id would miss it, and it could collide with an id that
// genuinely contains "�". Such a record is data corruption: the read is
// refused (named by record position when the id cannot be recovered
// faithfully), no partial results are returned and the file is never
// rewritten. A real "�", a correctly paired surrogate and the literal text
// \uD800 all stay ordinary ids. The shared readJobRecord engine judges this
// for both read passes.
//
// compiled_hash is a field whose presence is meaningful: records written
// before bindings existed simply omit it, and an explicit "" is the unbound
// state. But once the key appears its value must be a JSON string. A null is
// not "no binding" — it is damage to a binding the record claims to carry,
// and so is a number, boolean, array or object in its place. Reading either
// as the zero string would silently turn a bound job into an unbound one
// (and the next commit would drop the field entirely), so the read is
// refused as data corruption instead. A legal non-empty string keeps being
// matched against the pinned version's artifact by validateEnvelope, exactly
// as written.
//
// The field is recognized under any ASCII letter-case spelling, so a record
// carrying "COMPILED_HASH" (or any mixed-case form, escaped or not) is the
// same binding and follows the same rules: a single such key is read with
// the full string validation, and two spellings of the field on one record —
// even with byte-identical values — are a duplicate binding and corrupt the
// read rather than being resolved by key order.
//
// Non-ASCII spellings are not accepted even though encoding/json itself
// would fold them onto the field: its struct-tag matching uses Unicode case
// folding, under which "compiled_haſh" (U+017F long s, written directly or
// as the JSON escape u017f) names CompiledHash just like "compiled_hash".
// Such a lookalike is damage to the binding the record claims to carry and
// is refused whatever its value — null, a legal hash or an explicit "" —
// and even when a correctly spelled "compiled_hash" sits beside it, in
// either key order and whether the two values agree. The damaged binding
// must never read as an unbound job and disappear on the next commit.
//
// The pinned version field is held to its own uniqueness rule
// (rejectAmbiguousJobVersion): every spelling the ordinary decode fills
// Version from counts as that one field (isJobVersionKey): canonical
// "version", an ASCII letter-case variant such as "VERSION", and, since
// struct-tag matching folds with Unicode case rules, the long-s "verſion"
// (U+017F, direct or u017f-escaped). Two such spellings on one record are
// refused as data corruption whether the values agree or differ, whether
// both values are legal versions, and even when unrelated fields are
// interleaved between them. A non-ASCII "verſion" is refused only when
// another recognized spelling sits beside it; appearing by itself it is the
// single version field and keeps the current reading (the ordinary decode
// folds it onto Version). An illegal single value — a string, a float,
// null, or a non-positive version — is rejected exactly as before, by the
// ordinary decode or validateEnvelope.
//
// The owning circuit field is held to its own uniqueness rule
// (rejectAmbiguousJobCircuit): every spelling the ordinary decode fills
// Circuit from counts as that one field (isJobCircuitKey): canonical
// "circuit" and ASCII letter-case variants such as "CIRCUIT" or "CiRcUiT",
// JSON-escaped spellings included. Two such spellings on one record are
// refused as data corruption whether the values agree or differ, whether
// both name legal frozen circuits with trusted setups, and even when
// unrelated fields are interleaved between them — the job's owning circuit
// is never resolved by key order. A single recognized spelling keeps the
// current reading, and the value keeps being matched against circuit names
// exactly as written: "alpha" and "ALPHA" stay distinct circuits and no
// whitespace is trimmed.
//
// The identity field is held to the same uniqueness rule, and with the
// strictest attribution (rejectAmbiguousJobID): every spelling the ordinary
// decode fills ID from counts as that one field (isJobIDKey) — canonical
// "id", the three ASCII letter-case variants "ID", "Id" and "iD", and a
// JSON-escaped spelling that unescapes onto any of them; "id" has no
// non-ASCII case fold, so those four are exactly the recognized spellings.
// Two such spellings on one record make the job's query id a function of
// key order (encoding/json keeps the last value) and are refused as data
// corruption whether the two values agree or differ, whether both are
// present, non-empty and legal ids (legal Chinese, emoji and "�" included),
// even when unrelated fields (circuit, version, attempt, …) are interleaved
// between them, and even when neither spelling is the lowercase "id"
// ("ID" beside "Id", …) — no combination of variants bypasses the rule and
// two byte-identical spellings stay refused as well. Because the record
// then has no settled identity, the error locates it by its 1-based position
// in the jobs array ("job record #n") rather than quoting either candidate
// value, and names the field by its canonical name "id". A single
// recognized spelling keeps the current reading, and its value continues to
// match exactly as written: no case folding, trimming or U+FFFD repair.
//
// The shared readJobRecord scan enforces every key and structural rule once
// for both read passes; after it clears, this decode applies the rules the
// scan cannot — the binding-field lookalike, at-most-one binding and its
// string type — and then runs the ordinary struct decode for every other
// job field.
func (j *persistJob) UnmarshalJSON(raw []byte) error {
	const what = "stored job record"
	return decodeJob(raw, what, j)
}

// decodeJob reads one saved job record from raw through the shared engine and
// fills out. what is the generic name for a record with no legible id.
func decodeJob(raw []byte, what string, out *persistJob) error {
	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 {
		return corruptf("%s must be a JSON object", what)
	}
	dec := json.NewDecoder(bytes.NewReader(trimmed))
	r, err := readJobRecord(dec, what)
	if err != nil {
		return err
	}
	// A single complete object is the whole record, checked before any field
	// is judged (the old strict member walk led with shape and trailing-data
	// checks). At open this is already guaranteed by the directory scan; the
	// check keeps the single-record decode self-contained.
	if _, err := dec.Token(); err != io.EOF {
		return corruptf("%s is not valid JSON: trailing data after the object", what)
	}

	// Name the record the way this pass always has: an ordinary struct probe
	// folds id spellings the same way the final decode does (so an "ID"
	// variant still names the record), and a missing or non-string id leaves
	// the generic name. The probe only labels errors; the id is decoded for
	// real by the ordinary pass below. An id whose bytes encoding/json would
	// repair (invalid UTF-8, an unpaired surrogate) is never quoted: it cannot
	// be recovered faithfully, so the generic positional name stands and the
	// idEncodingErr message below locates the record and field by position.
	where := what
	var idProbe struct {
		ID string `json:"id"`
	}
	if err := json.Unmarshal(raw, &idProbe); err == nil && idProbe.ID != "" && r.idEncodingErr == nil {
		where = fmt.Sprintf("stored job record %q", idProbe.ID)
	}

	// The scan-owned findings (id, version and circuit ambiguity, exact and
	// nested duplicate keys) outrank every binding finding, exactly as when
	// the directory scan ran ahead of this decode. (During an open the scan
	// has already enforced them, so this is a no-op there; it keeps the
	// single-record decoder self-contained.) The id-ambiguity finding is
	// always attributed positionally inside judge, so the probe-derived
	// "where" (which may fold an "ID" variant) never labels a record that
	// carries two ids with one of them.
	if err := r.judge(where); err != nil {
		return err
	}

	// Reject a non-ASCII spelling that encoding/json's Unicode-folded tag
	// matching would silently read as this field ("compiled_haſh" with long
	// s, directly written or ſ-escaped), whatever its value and whether or
	// not a correctly spelled key accompanies it. It must never be ignored as
	// an unknown member, which would let a damaged binding read unbound.
	if alias := compiledHashLookalike(r.memberKeys()); alias != "" {
		return corruptf("%s carries the binding field %q under non-ASCII spelling %q; such a lookalike spelling is data corruption",
			where, compiledHashKey, alias)
	}
	// Every accepted spelling of the binding field counts as the same one
	// field; the record may carry it at most once, however it is capitalized.
	bindingKeys := r.bindingKeys()
	if len(bindingKeys) > 1 {
		sort.Strings(bindingKeys)
		quoted := make([]string, len(bindingKeys))
		for i, k := range bindingKeys {
			quoted[i] = strconv.Quote(k)
		}
		return corruptf("%s carries the binding field %q more than once (as %s)",
			where, compiledHashKey, strings.Join(quoted, ", "))
	}
	compiledHash := ""
	hasBinding := false
	if len(bindingKeys) == 1 {
		// The field is always quoted by its canonical name in the diagnostic,
		// regardless of the accepted spelling it was written under.
		hash, err := storedRecordShape.string(r.valueOf(bindingKeys[0]), where+` field "compiled_hash"`)
		if err != nil {
			return err
		}
		compiledHash, hasBinding = hash, true
	}
	// With zero or one recognized version spelling, the ordinary decode below
	// already yields the current value: a single canonical/ASCII/long-s
	// spelling folds onto Version, and a missing version reads as 0 and is
	// rejected by validateEnvelope as a job bound to an unknown circuit. Illegal
	// single values (a string, a float, null, zero or negative) keep being
	// rejected by that same decode or the envelope validation, so nothing is
	// picked here.
	type plainJob persistJob
	var decoded plainJob
	if err := json.Unmarshal(raw, &decoded); err != nil {
		return corruptf("%s is not valid JSON: %v", what, err)
	}
	if hasBinding {
		decoded.CompiledHash = compiledHash
	}
	*out = persistJob(decoded)
	return nil
}

package zkcircuit

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"strconv"
	"unicode/utf8"
)

// Saved circuit records used to be read and field-checked twice: once while
// the committed envelope was tokenized to reject a repeated object key
// (scanCircuitArray) and again while each circuits element was decoded into a
// persistCircuit (persistCircuit.UnmarshalJSON). Each pass gathered the
// record's member keys on its own and carried its own copy of the object,
// required-field and duplicate-key rules, so the judgment of what one
// committed circuit record may look like lived in two places that had to
// agree by construction.
//
// This file is now the single home of a saved circuit record's reading rules:
// the persistCircuit shape, the exact member spellings it accepts
// (name / version / constraints / public_inputs / private_inputs / frozen /
// description, plus the one optional definition), the strict scalar typing
// and the name exact-readback rule, together with one per-record reading
// engine (readCircuitRecord) both read passes drive. The directory scan and
// the single-record decode hence tokenize one record once and judge its keys
// and structure through the same code, which also covers two byte-identical
// member keys — a case a post-decode member map could not see on its own.
//
// Circuit fields are stricter than envelope and job fields: they are
// recognized ONLY under their exact lowercase wire spellings. Keys reach
// every rule below already JSON-unescaped, so a key written with a \uXXXX
// escape is judged on its decoded spelling, but no letter-case folding is
// applied — "FROZEN", "Name" and a long-s lookalike such as "frozeſ" are all
// ordinary unknown fields and corrupt the read the same way "note" does.
//
// Only the reading of saved circuit records is consolidated here. The public
// behavior — which values load, which are refused, how the failure is located
// and in what order findings surface — is unchanged; the commands, the Go
// entry points and the on-disk format stay as they were. In particular the
// two read passes keep their historical division of labor and precedence
// because an open always runs the directory scan before the typed decode: the
// scan owns structural findings and exact repeated keys (readCircuitRecord as
// driven by scanCircuitArray) over every record first, while the typed decode
// owns unknown fields, the per-field required/type checks, the name
// exact-readback rule and the definition decode (decodeCircuit).

type persistCircuit struct {
	Name          string             `json:"name"`
	Version       int                `json:"version"`
	Constraints   int                `json:"constraints"`
	PublicInputs  int                `json:"public_inputs"`
	PrivateInputs int                `json:"private_inputs"`
	Frozen        bool               `json:"frozen"`
	Description   string             `json:"description"`
	Definition    *persistDefinition `json:"definition,omitempty"`
}

// persistCircuitFields are the eight fields a committed circuit record may
// carry, under their exact (standard lowercase) wire spellings. Seven are
// required with the exact JSON type the writer emits; definition alone is
// optional (absent or null both mean the legacy counts-only state).
var persistCircuitFields = []string{
	"name", "version", "constraints", "public_inputs", "private_inputs",
	"frozen", "description", "definition",
}

// storedRecordShape is the shared strict-JSON rule set (definition_schema.go)
// tagged for committed data: every structural failure in a stored circuit or
// job record is data corruption, never a bad request.
var storedRecordShape = jsonShape{fail: corruptf}

// circuitMember is one member of a saved circuit record as seen during the
// single per-record pass: its already-JSON-unescaped key and its raw value.
type circuitMember struct {
	key   string
	value json.RawMessage
}

// readCircuitRecord consumes exactly one circuit record value the decoder is
// positioned at — including its opening token — and returns the members. The
// two passes drive it with a different key rule, so one tokenization serves
// both historical tiers:
//
//   - The directory scan passes allowedFields == nil: it does not judge which
//     keys are valid, only structure and a repeated key of ANY spelling. That
//     matches the old envelope scan, which attributed a repeated member to the
//     record whether or not the name was known.
//   - The typed decode passes the eight allowed spellings: at each key
//     position an unknown spelling is named first and a repeated allowed key
//     second, in document order — the precedence of the old strict member
//     walk (so an unknown member appearing before another key's second
//     occurrence is named as unknown, and an unknown key appearing twice is
//     named as unknown rather than duplicate).
//
// In both tiers the key judgment happens before that occurrence's value is
// decoded, the point at which both old passes rejected, so a malformed value
// following the offending key never substitutes a syntax error. Every other
// token is consumed unless the record is damaged. A null element or a
// non-object element is structural damage named by positional. positional is
// the name used to locate the record: the directory scan passes
// "circuit record #<1-based index>", the typed decode passes
// "stored circuit record".
//
// Member values are captured whole without descending: a nested value such as
// the constraint definition owns its own (more precise) strict decoder
// during the typed decode.
func readCircuitRecord(dec *json.Decoder, positional string, allowedFields []string) ([]circuitMember, error) {
	open, err := dec.Token()
	if err != nil {
		return nil, corruptf("%s is not valid JSON: %v", positional, err)
	}
	if open == nil {
		return nil, corruptf("%s must be a JSON object, not null", positional)
	}
	if open != json.Delim('{') {
		return nil, corruptf("%s must be a JSON object", positional)
	}

	var allowed map[string]bool
	if allowedFields != nil {
		allowed = make(map[string]bool, len(allowedFields))
		for _, f := range allowedFields {
			allowed[f] = true
		}
	}
	var members []circuitMember
	seen := make(map[string]bool)
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return nil, corruptf("%s is not valid JSON: %v", positional, err)
		}
		key, ok := keyTok.(string)
		if !ok {
			return nil, corruptf("%s is not valid JSON", positional)
		}
		// Keys arrive already JSON-unescaped, so a key spelled through a
		// \uXXXX escape is judged on its decoded spelling. The typed tier
		// names an unknown spelling ahead of a repetition; the scan tier only
		// sees repetitions. Both judgments pre-date the value decode, as they
		// always did.
		if allowed != nil && !allowed[key] {
			return nil, corruptf("%s has unknown field %q", positional, key)
		}
		if seen[key] {
			return nil, corruptf("%s contains duplicate field %q", positional, key)
		}
		seen[key] = true
		var value json.RawMessage
		if err := dec.Decode(&value); err != nil {
			return nil, corruptf("%s is not valid JSON: %v", positional, err)
		}
		members = append(members, circuitMember{key: key, value: value})
	}
	if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
		return nil, corruptf("%s is not valid JSON", positional)
	}
	return members, nil
}

// scanCircuitArray consumes one "circuits" value positioned at its opening
// bracket and reads every record through the shared per-record engine in
// scan mode (no allowed-field list), which names each structural problem or
// repeated key before the scan moves on. It is the directory-wide pre-check
// counterpart of decodeCircuit and exists so a structural problem inside one
// circuit is attributed to that record by its 1-based position rather than to
// an opaque "circuits" element index. A null array stays the pre-existing
// "no records" reading.
func scanCircuitArray(dec *json.Decoder) error {
	tok, err := dec.Token()
	if err != nil {
		return corruptf("data file envelope field \"circuits\" is not valid JSON: %v", err)
	}
	if tok == nil { // null: json.Unmarshal would produce no records
		return nil
	}
	if tok != json.Delim('[') {
		return corruptf("data file envelope field \"circuits\" must be an array")
	}
	index := 0
	for dec.More() {
		index++
		if _, err := readCircuitRecord(dec, fmt.Sprintf("circuit record #%d", index), nil); err != nil {
			return err
		}
	}
	if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
		return corruptf("data file envelope field \"circuits\" is not valid JSON")
	}
	return nil
}

// Strict decoding of committed circuit records.
//
// A circuit record in data.json must name each of name, version, constraints,
// public_inputs, private_inputs, frozen and description exactly once, with
// the exact JSON type the writer emits (string / integer / integer / integer
// / integer / boolean / string). A missing key, a null, a wrong type or a
// repeated key is data corruption and refuses the whole directory read: a
// missing or null frozen flag must not silently read as false (turning a
// frozen version back into an editable draft), and a repeated key must not
// resolve to its last value. An explicit 0, false or "" is an ordinary value
// and stays legal. The definition member remains the one optional field: it
// may be absent or null (the legacy counts-only state, which still compiles
// no further than "constraint definition missing"); when present it goes
// through the strict persistDefinition decoder, keeping the constraint order,
// input layout and compiled hash of defined versions intact.
//
// The name field carries one rule beyond shape: its raw JSON string token
// must denote its value exactly — valid UTF-8 in the literal portions and no
// unpaired \uXXXX surrogate escapes (checkStoredStringEncoding). Both damage
// shapes decode to U+FFFD replacement characters under encoding/json, which
// would rename the circuit on read; they are data corruption, and the whole
// directory read is refused. Only the name is judged this way; every other
// field keeps the ordinary decoding rules.
//
// Only shape is judged here. The domain rules (non-blank name, positive
// version and constraint count, non-negative input counts) keep being
// re-checked by validateEnvelope.

func (c *persistCircuit) UnmarshalJSON(raw []byte) error {
	const what = "stored circuit record"
	return decodeCircuit(raw, what, c)
}

// decodeCircuit reads one saved circuit record from raw through the shared
// engine and fills out. what is the generic name for a record located
// positionally; the envelope read prefixes it with the record index when it
// re-tags the error.
//
// Findings surface in the fixed order the two historical passes produced
// together: the object gate and trailing data, then the first unknown or
// repeated member in document order (an unknown spelling is named before a
// repetition at the same key position, exactly as the old strict member walk
// ordered it), then the field-by-field required/type checks with the name
// encoding rule right after the name string read, and only then the optional
// definition's own decode.
func decodeCircuit(raw []byte, what string, out *persistCircuit) error {
	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 {
		return corruptf("%s must be a JSON object", what)
	}
	dec := json.NewDecoder(bytes.NewReader(trimmed))
	memberList, err := readCircuitRecord(dec, what, persistCircuitFields)
	if err != nil {
		return err
	}

	// A single complete object is the whole record. Unknown and repeated
	// members were already rejected during the single tokenization above, in
	// the old strict-member order (unknown before repetition, in document
	// order); this trailing-data check follows that gate, exactly as before.
	// At open the directory scan already guarantees it; the check keeps the
	// single-record decoder self-contained.
	if _, err := dec.Token(); err != io.EOF {
		return corruptf("%s is not valid JSON: trailing data after the object", what)
	}

	var c persistCircuit

	// The members are the allowed spellings without repeats, so the strict
	// required/scalar reads can address them by name.
	members := make(map[string]json.RawMessage, len(memberList))
	for _, m := range memberList {
		members[m.key] = m.value
	}

	requireString := func(key string, dst *string) error {
		v, err := storedRecordShape.require(members, key, what)
		if err != nil {
			return err
		}
		s, err := storedRecordShape.string(v, what+" field "+strconv.Quote(key))
		if err != nil {
			return err
		}
		*dst = s
		return nil
	}
	requireInt := func(key string, dst *int) error {
		v, err := storedRecordShape.require(members, key, what)
		if err != nil {
			return err
		}
		n, err := storedRecordShape.int(v, what+" field "+strconv.Quote(key))
		if err != nil {
			return err
		}
		*dst = n
		return nil
	}

	if err := requireString("name", &c.Name); err != nil {
		return err
	}
	// The name is the version's identity and must read back as the exact
	// value that was committed. encoding/json silently rewrites both invalid
	// UTF-8 bytes and unpaired \uXXXX surrogate escapes to U+FFFD, so the
	// decoded string alone cannot tell a damaged name apart from one that
	// legitimately contains "�". Judge the raw JSON token instead.
	if err := checkStoredStringEncoding(members["name"], what+` field "name"`, "committed name"); err != nil {
		return err
	}
	if err := requireInt("version", &c.Version); err != nil {
		return err
	}
	if err := requireInt("constraints", &c.Constraints); err != nil {
		return err
	}
	if err := requireInt("public_inputs", &c.PublicInputs); err != nil {
		return err
	}
	if err := requireInt("private_inputs", &c.PrivateInputs); err != nil {
		return err
	}
	frozenRaw, err := storedRecordShape.require(members, "frozen", what)
	if err != nil {
		return err
	}
	c.Frozen, err = storedRecordShape.bool(frozenRaw, what+" field "+strconv.Quote("frozen"))
	if err != nil {
		return err
	}
	if err := requireString("description", &c.Description); err != nil {
		return err
	}

	// definition is the only optional member: absent or null both mean the
	// counts-only legacy state.
	if defRaw, present := members["definition"]; present {
		if string(bytes.TrimSpace(defRaw)) != "null" {
			var def persistDefinition
			if err := json.Unmarshal(defRaw, &def); err != nil {
				var se StoreError
				if errors.As(err, &se) {
					return err // already reported as data corruption
				}
				return corruptf("%s field %s is not a valid constraint definition: %v", what, strconv.Quote("definition"), err)
			}
			c.Definition = &def
		}
	}

	*out = c
	return nil
}

// checkStoredStringEncoding enforces an identity field's exact-readback rule
// on the raw JSON string token of a committed value (a circuit record's name,
// a job record's id). The string has already been decoded by the strict
// member read, so the token is known to be one complete, well-formed JSON
// string; this walk judges only what that decode silently repairs:
//
//   - invalid UTF-8 bytes in the literal (unescaped) portions — a lone
//     continuation byte, a truncated multi-byte character, an overlong
//     form — which encoding/json rewrites to U+FFFD, and
//   - \uXXXX escapes forming an unpaired surrogate — a high surrogate not
//     immediately followed by its low-surrogate escape, or a low surrogate
//     standing alone — which are rewritten to U+FFFD the same way.
//
// Both would make the record read back under a different value than the bytes
// on disk carry, so the record is data corruption rather than a value that
// legitimately decodes to a replacement character it never had. noun is the
// word naming the value in diagnostics ("committed name" / "committed job
// id"); what locates the record and field, e.g.
// `stored circuit record field "name"` or `stored job record "j1" field
// "id"`. A legal surrogate pair decodes to its astral character, an actually
// committed "�" (written directly or as a U+FFFD escape) is an ordinary
// value, and the literal six characters "\uD800" — written with an escaped
// backslash — carry no escape at all: all three keep their exact value.
func checkStoredStringEncoding(raw json.RawMessage, what, noun string) error {
	token := bytes.TrimSpace(raw)
	// The token is a complete JSON string (the strict string read above
	// succeeded), so every escape is well-formed and the walk stays in
	// bounds; only the replacement-prone content is judged.
	for i := 1; i < len(token)-1; {
		c := token[i]
		if c == '\\' {
			if token[i+1] != 'u' {
				i += 2 // a simple escape: \" \\ \/ \b \f \n \r \t
				continue
			}
			code, _ := strconv.ParseUint(string(token[i+2:i+6]), 16, 32)
			switch {
			case code >= 0xD800 && code <= 0xDBFF:
				// A high surrogate is whole only when its low-surrogate
				// escape follows immediately.
				if i+12 <= len(token) && token[i+6] == '\\' && token[i+7] == 'u' {
					lo, _ := strconv.ParseUint(string(token[i+8:i+12]), 16, 32)
					if lo >= 0xDC00 && lo <= 0xDFFF {
						i += 12
						continue
					}
				}
				return corruptf("%s contains an unpaired high surrogate escape (\\u%04X); the %s would not read back unchanged", what, code, noun)
			case code >= 0xDC00 && code <= 0xDFFF:
				return corruptf("%s contains an unpaired low surrogate escape (\\u%04X); the %s would not read back unchanged", what, code, noun)
			}
			i += 6
			continue
		}
		if c < utf8.RuneSelf {
			i++
			continue
		}
		r, size := utf8.DecodeRune(token[i:])
		if r == utf8.RuneError && size == 1 {
			return corruptf("%s contains invalid UTF-8 bytes; the %s would not read back unchanged", what, noun)
		}
		i += size
	}
	return nil
}

