307			t.Run(label, func(t *testing.T) {
308				raw := []byte(`{"format":1,"circuits":[` +
309					`{"name":"c","version":1,"constraints":1,"public_inputs":1,"private_inputs":1,"frozen":true,"description":""}` +
310					`],"setups":[{"name":"c","version":1}],"jobs":[` +
311					`{"id":` + tc.idJSON + `,"circuit":"c","version":1,"kind":"prove","attempt":1}]}`)
312				dir := plantRawEnvelope(t, raw)
313	
314				s, err := Open(dir)
315				if err != nil {
316					t.Fatalf("legal id refused: %v", err)
317				}
318				defer s.Close()
319				got, err := s.GetJob(tc.want)
320				if err != nil {
321					t.Fatalf("id %q did not read back: %v", tc.want, err)
322				}
323				if got.ID != tc.want {
324					t.Fatalf("id changed on read: want %q, got %q", tc.want, got.ID)
325				}
326			})
327		}
328	}
329	
330	// Once a committed id is corrupt, every operation refuses at open: reads
331	// return nothing partial, submissions and unrelated mutations commit
332	// nothing, and the file stays byte-for-byte in place.
333	func TestCorruptJobIDDirectoryFullyRefused(t *testing.T) {
334		raw := rawJobEnvelope(`"作业\uD800"`)
335		dir := plantRawEnvelope(t, raw)
336	
337		if _, err := Open(dir); !errors.Is(err, ErrDataCorrupt) {
338			t.Fatalf("open: want ErrDataCorrupt, got %v", err)
339		}
340		left, err := os.ReadFile(filepath.Join(dir, dirDataFile))
341		if err != nil {
342			t.Fatal(err)
343		}
344		if string(left) != string(raw) {
345			t.Fatalf("data.json changed across refused open\nwant: %q\n got: %q", raw, left)
346		}
347	}
348

